{"path":"/workspace/backend/db.go","command":"create","file_text":"package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

type Store struct {
	PG    *pgxpool.Pool
	Mongo *mongo.Client
	Audit *mongo.Collection
}

func Connect(ctx context.Context) (*Store, error) {
	pgURL := os.Getenv("DATABASE_URL")
	if pgURL == "" {
		pgURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	pg, err := pgxpool.New(ctx, pgURL)
	if err != nil {
		return nil, fmt.Errorf("pg: %w", err)
	}
	if err := pg.Ping(ctx); err != nil {
		return nil, fmt.Errorf("pg ping: %w", err)
	}

	mongoURI := os.Getenv("MONGODB_URI")
	if mongoURI == "" {
		mongoURI = "mongodb://127.0.0.1:27017/arena"
	}
	mc, err := mongo.Connect(options.Client().ApplyURI(mongoURI))
	if err != nil {
		return nil, fmt.Errorf("mongo: %w", err)
	}
	if err := mc.Ping(ctx, nil); err != nil {
		return nil, fmt.Errorf("mongo ping: %w", err)
	}
	dbName := "arena"
	if i := strings.LastIndex(mongoURI, "/"); i >= 0 {
		rest := mongoURI[i+1:]
		if q := strings.Index(rest, "?"); q >= 0 {
			rest = rest[:q]
		}
		if rest != "" {
			dbName = rest
		}
	}
	return &Store{
		PG:    pg,
		Mongo: mc,
		Audit: mc.Database(dbName).Collection("audit_entries"),
	}, nil
}

func (s *Store) Close() {
	if s.PG != nil {
		s.PG.Close()
	}
	if s.Mongo != nil {
		_ = s.Mongo.Disconnect(context.Background())
	}
}

func (s *Store) Ready(ctx context.Context) bool {
	if err := s.PG.Ping(ctx); err != nil {
		return false
	}
	if err := s.Mongo.Ping(ctx, nil); err != nil {
		return false
	}
	return true
}

func (s *Store) ApplySchema(ctx context.Context, sql string) error {
	_, err := s.PG.Exec(ctx, sql)
	return err
}

func (s *Store) MaterializeMongo(ctx context.Context) error {
	db := s.Audit.Database()
	names := []string{"audit_entries", "realtime_events"}
	existing, _ := db.ListCollectionNames(ctx, bson.M{})
	have := map[string]bool{}
	for _, n := range existing {
		have[n] = true
	}
	for _, n := range names {
		if !have[n] {
			_ = db.CreateCollection(ctx, n)
		}
	}
	_, _ = db.Collection("audit_entries").Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "auditId", Value: 1}}, Options: options.Index().SetUnique(true)},
		{Keys: bson.D{{Key: "actorId", Value: 1}, {Key: "occurredAt", Value: -1}}},
		{Keys: bson.D{{Key: "entityType", Value: 1}, {Key: "entityId", Value: 1}, {Key: "occurredAt", Value: -1}}},
		{Keys: bson.D{{Key: "action", Value: 1}, {Key: "occurredAt", Value: -1}}},
		{Keys: bson.D{{Key: "role", Value: 1}}},
		{Keys: bson.D{{Key: "success", Value: 1}}},
		{Keys: bson.D{{Key: "occurredAt", Value: -1}}},
	})
	_, _ = db.Collection("realtime_events").Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "id", Value: 1}}},
		{Keys: bson.D{{Key: "createdAt", Value: -1}}},
	})
	return nil
}

func (s *Store) Reset(ctx context.Context, schemaSQL string) error {
	// Drop all application tables
	tables := []string{
		"realtime_events", "meta", "serviceability_snapshots", "disruptions",
		"idempotency", "timeline", "worker_locations", "checkpoints", "handoffs",
		"capacity_reservations", "assignments", "journey_stops", "journey_samples",
		"journeys", "samples", "connections", "laboratory_acceptance", "locations",
		"sample_types", "sessions", "certifications", "users",
	}
	for _, t := range tables {
		if _, err := s.PG.Exec(ctx, "DROP TABLE IF EXISTS "+t+" CASCADE"); err != nil {
			return fmt.Errorf("drop %s: %w", t, err)
		}
	}
	if err := s.ApplySchema(ctx, schemaSQL); err != nil {
		return err
	}
	// Mongo
	_ = s.Audit.Database().Collection("audit_entries").Drop(ctx)
	_ = s.Audit.Database().Collection("realtime_events").Drop(ctx)
	if err := s.MaterializeMongo(ctx); err != nil {
		return err
	}
	return seedDefaultSampleTypes(ctx, s)
}

