	return scanUser(s.PG.QueryRow(ctx, `SELECT id, username, password_hash, email, full_name, phone, roles, qualifications, assigned_location_id, active, available, capacity_units, last_offered_at, decline_count, decline_window_start FROM users WHERE username=$1`, username))
}

func (s *Store) GetUserByID(ctx context.Context, id uuid.UUID) (*User, error) {
	return scanUser(s.PG.QueryRow(ctx, `SELECT id, username, password_hash, email, full_name, phone, roles, qualifications, assigned_location_id, active, available, capacity_units, last_offered_at, decline_count, decline_window_start FROM users WHERE id=$1`, id))
}

func (s *Store) ListUsers(ctx context.Context) ([]User, error) {
	rows, err := s.PG.Query(ctx, `SELECT id, username, password_hash, email, full_name, phone, roles, qualifications, assigned_location_id, active, available, capacity_units, last_offered_at, decline_count, decline_window_start FROM users`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []User
	for rows.Next() {
		u, err := scanUserRow(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, *u)
	}
	return out, rows.Err()
}

func scanUser(row pgx.Row) (*User, error) {
	var u User
	err := row.Scan(&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone, &u.Roles, &u.Qualifications, &u.AssignedLocationID, &u.Active, &u.Available, &u.CapacityUnits, &u.LastOfferedAt, &u.DeclineCount, &u.DeclineWindowStart)
	if err == pgx.ErrNoRows {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	if u.Roles == nil {
		u.Roles = []string{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	return &u, nil
}

func scanUserRow(rows pgx.Rows) (*User, error) {
	var u User
	err := rows.Scan(&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone, &u.Roles, &u.Qualifications, &u.AssignedLocationID, &u.Active, &u.Available, &u.CapacityUnits, &u.LastOfferedAt, &u.DeclineCount, &u.DeclineWindowStart)
	if err != nil {
		return nil, err
	}
	if u.Roles == nil {
		u.Roles = []string{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	return &u, nil
}

func (s *Store) ReplaceCertifications(ctx context.Context, userID uuid.UUID, certs []Certification) error {
	if _, err := s.PG.Exec(ctx, `DELETE FROM certifications WHERE user_id=$1`, userID); err != nil {
		return err
	}
	for _, c := range certs {
		var exp *time.Time
		if c.ExpiresAt != nil && *c.ExpiresAt != "" {
			t, err := time.Parse(time.RFC3339, *c.ExpiresAt)
			if err != nil {
				t2, err2 := time.Parse(time.RFC3339Nano, *c.ExpiresAt)
				if err2 != nil {
					return fmt.Errorf("invalid certification expiry")
				}
				t = t2
			}
			exp = &t
		}
		if _, err := s.PG.Exec(ctx, `INSERT INTO certifications (id, user_id, code, active, expires_at) VALUES ($1,$2,$3,$4,$5)`,
			uuid.New(), userID, c.Code, c.Active, exp); err != nil {
			return err
		}
	}
	return nil
}

func (s *Store) GetCertifications(ctx context.Context, userID uuid.UUID) ([]Certification, error) {
	rows, err := s.PG.Query(ctx, `SELECT code, active, expires_at FROM certifications WHERE user_id=$1`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []Certification
	for rows.Next() {
		var c Certification
		var exp *time.Time
		if err := rows.Scan(&c.Code, &c.Active, &exp); err != nil {
			return nil, err
		}
		c.ExpiresAt = fmtTimePtr(exp)
		out = append(out, c)
	}
	if out == nil {
		out = []Certification{}
	}
	return out, rows.Err()
}

