func (s *Store) BumpDecline(ctx context.Context, id uuid.UUID) error {
	_, err := s.PG.Exec(ctx, `
		UPDATE users SET
			decline_count = CASE WHEN decline_window_start IS NULL OR decline_window_start < now() - interval '30 minutes' THEN 1 ELSE decline_count + 1 END,
			decline_window_start = CASE WHEN decline_window_start IS NULL OR decline_window_start < now() - interval '30 minutes' THEN now() ELSE decline_window_start END
		WHERE id=$1`, id)
	return err
}

