		Scan(&st.ID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification, &st.ContainerType, &st.TemperatureMinC, &st.TemperatureMaxC, &st.IncompatibleSampleTypes, &st.RequiresCooledRoute, &st.BatchingAllowed)
