func (s *Store) ConfigureCapacity(ctx context.Context, resourceID uuid.UUID, units, cooled int) (string, error) {
	tag, err := s.PG.Exec(ctx, `UPDATE locations SET capacity_units=$2, cooled_capacity_units=$3 WHERE id=$1`, resourceID, units, cooled)
	if err != nil {
		return "", err
	}
	if tag.RowsAffected() > 0 {
		return "location", nil
	}
	tag, err = s.PG.Exec(ctx, `UPDATE connections SET capacity_units=$2, cooled_capacity_units=$3 WHERE id=$1`, resourceID, units, cooled)
	if err != nil {
		return "", err
	}
	if tag.RowsAffected() > 0 {
		return "connection", nil
	}
	return "", nil
}

func (s *Store) ReserveCapacity(ctx context.Context, resourceType string, resourceID, sampleID, journeyID uuid.UUID, cooled bool, units int) error {
	col := "reserved_units"
	table := "locations"
	if resourceType == "connection" {
		table = "connections"
	}
	if cooled {
		col = "cooled_reserved_units"
	}
	tag, err := s.PG.Exec(ctx, fmt.Sprintf(`UPDATE %s SET %s = %s + $2 WHERE id=$1`, table, col, col), resourceID, units)
	if err != nil {
		return err
	}
	if tag.RowsAffected() == 0 {
		return fmt.Errorf("resource not found")
	}
	_, err = s.PG.Exec(ctx, `INSERT INTO capacity_reservations (id, resource_type, resource_id, sample_id, journey_id, cooled, units, active) VALUES ($1,$2,$3,$4,$5,$6,$7,true)`,
		uuid.New(), resourceType, resourceID, sampleID, journeyID, cooled, units)
	return err
}

func (s *Store) ReleaseReservationsForSample(ctx context.Context, sampleID uuid.UUID) error {
	rows, err := s.PG.Query(ctx, `SELECT id, resource_type, resource_id, cooled, units FROM capacity_reservations WHERE sample_id=$1 AND active=true`, sampleID)
	if err != nil {
		return err
	}
	defer rows.Close()
	type rec struct {
		id, resID uuid.UUID
		typ       string
		cooled    bool
		units     int
	}
	var recs []rec
	for rows.Next() {
		var r rec
		if err := rows.Scan(&r.id, &r.typ, &r.resID, &r.cooled, &r.units); err != nil {
			return err
		}
		recs = append(recs, r)
	}
	rows.Close()
	for _, r := range recs {
		col := "reserved_units"
		table := "locations"
		if r.typ == "connection" {
			table = "connections"
		}
		if r.cooled {
			col = "cooled_reserved_units"
		}
		if _, err := s.PG.Exec(ctx, fmt.Sprintf(`UPDATE %s SET %s = GREATEST(%s - $2, 0) WHERE id=$1`, table, col, col), r.resID, r.units); err != nil {
			return err
		}
		if _, err := s.PG.Exec(ctx, `UPDATE capacity_reservations SET active=false WHERE id=$1`, r.id); err != nil {
			return err
		}
	}
	return nil
}

