func scanSampleFields(scan func(dest ...any) error) (*Sample, error) {
	var sm Sample
	var exc []byte
	err := scan(&sm.ID, &sm.RequestID, &sm.RequesterID, &sm.OriginLat, &sm.OriginLng, &sm.OriginType, &sm.OriginNodeID,
		&sm.RequestedAt, &sm.DeliveryDeadline, &sm.EarliestCollectionAt, &sm.LatestCollectionAt,
		&sm.SampleTypeID, &sm.ContainerType, &sm.TemperatureMinC, &sm.TemperatureMaxC, &sm.IncompatibleSampleTypes,
		&sm.Serviceability, &sm.ServiceabilityReason, &sm.Status, &sm.Sealed, &sm.SealedAt, &sm.AlreadySealed,
		&sm.CurrentHolderID, &sm.TargetLaboratoryID, &sm.ReceivedLaboratoryID, &sm.ReceivedAt,
		&sm.ActiveJourneyID, &sm.LatestLat, &sm.LatestLng, &sm.LocationRecordedAt, &exc, &sm.PendingHandoffID)
	if err != nil {
		return nil, err
	}
	if sm.IncompatibleSampleTypes == nil {
		sm.IncompatibleSampleTypes = []uuid.UUID{}
	}
	if len(exc) > 0 && string(exc) != "null" {
		_ = json.Unmarshal(exc, &sm.Exception)
	}
	return &sm, nil
}

