func (s *Store) AddTimeline(ctx context.Context, action, actorID, role, entityType, entityID string, success bool, details map[string]interface{}) (int64, error) {
	if details == nil {
		details = map[string]interface{}{}
	}
	b, _ := json.Marshal(details)
	var id int64
	err := s.PG.QueryRow(ctx, `INSERT INTO timeline (action, actor_id, role, entity_type, entity_id, success, details) VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING event_id`,
		action, actorID, role, entityType, entityID, success, b).Scan(&id)
	return id, err
}

func (s *Store) ListTimeline(ctx context.Context, entityType, entityID string) ([]TimelineEntry, error) {
	rows, err := s.PG.Query(ctx, `SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details FROM timeline WHERE entity_type=$1 AND entity_id=$2 ORDER BY occurred_at, event_id`, entityType, entityID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []TimelineEntry
	for rows.Next() {
		var e TimelineEntry
		var det []byte
		var at time.Time
		if err := rows.Scan(&e.EventID, &e.Action, &e.ActorID, &e.Role, &e.EntityType, &e.EntityID, &e.Success, &at, &det); err != nil {
			return nil, err
		}
		e.OccurredAt = fmtTime(at)
		e.Details = map[string]interface{}{}
		if len(det) > 0 {
			_ = json.Unmarshal(det, &e.Details)
		}
		out = append(out, e)
	}
	if out == nil {
		out = []TimelineEntry{}
	}
	return out, rows.Err()
}

func (s *Store) AddRealtime(ctx context.Context, typ, entityType, entityID string, payload map[string]interface{}) (int64, error) {
	if payload == nil {
		payload = map[string]interface{}{}
	}
	b, _ := json.Marshal(payload)
	var id int64
	err := s.PG.QueryRow(ctx, `INSERT INTO realtime_events (type, entity_type, entity_id, payload) VALUES ($1,$2,$3,$4) RETURNING id`,
		typ, entityType, entityID, b).Scan(&id)
	return id, err
}

func (s *Store) ListRealtime(ctx context.Context, since int64) ([]map[string]interface{}, int64, error) {
	rows, err := s.PG.Query(ctx, `SELECT id, type, entity_type, entity_id, payload, created_at FROM realtime_events WHERE id > $1 ORDER BY id`, since)
	if err != nil {
		return nil, since, err
	}
	defer rows.Close()
	var out []map[string]interface{}
	cursor := since
	for rows.Next() {
		var id int64
		var typ, et, eid string
		var payload []byte
		var at time.Time
		if err := rows.Scan(&id, &typ, &et, &eid, &payload, &at); err != nil {
			return nil, since, err
		}
		p := map[string]interface{}{}
		_ = json.Unmarshal(payload, &p)
		out = append(out, map[string]interface{}{
			"id": id, "type": typ, "entityType": et, "entityId": eid, "payload": p, "createdAt": fmtTime(at),
		})
		cursor = id
	}
	if out == nil {
		out = []map[string]interface{}{}
	}
	return out, cursor, rows.Err()
}

func (s *Store) GetIdempotency(ctx context.Context, key string, userID uuid.UUID, endpoint string) (hash string, status int, body []byte, ok bool, err error) {
	err = s.PG.QueryRow(ctx, `SELECT request_hash, status_code, response_body FROM idempotency WHERE key=$1 AND user_id=$2 AND endpoint=$3`, key, userID, endpoint).
		Scan(&hash, &status, &body)
	if err == pgx.ErrNoRows {
		return "", 0, nil, false, nil
	}
	if err != nil {
		return "", 0, nil, false, err
	}
	return hash, status, body, true, nil
}

func (s *Store) PutIdempotency(ctx context.Context, key string, userID uuid.UUID, endpoint, hash string, status int, body []byte) error {
	_, err := s.PG.Exec(ctx, `INSERT INTO idempotency (key, user_id, endpoint, request_hash, status_code, response_body) VALUES ($1,$2,$3,$4,$5,$6)
		ON CONFLICT (key, user_id, endpoint) DO NOTHING`, key, userID, endpoint, hash, status, body)
	return err
}

func (s *Store) NetworkRevision(ctx context.Context) (int, error) {
	var v string
	err := s.PG.QueryRow(ctx, `SELECT value FROM meta WHERE key='network_revision'`).Scan(&v)
	if err != nil {
		return 1, err
	}
	var n int
	fmt.Sscanf(v, "%d", &n)
	if n == 0 {
		n = 1
	}
	return n, nil
}

func (s *Store) BumpNetworkRevision(ctx context.Context) (int, error) {
	var n int
	err := s.PG.QueryRow(ctx, `
		UPDATE meta SET value = (value::int + 1)::text WHERE key='network_revision' RETURNING value::int`).Scan(&n)
	return n, err
}

func (s *Store) CurrentSnapshot(ctx context.Context) (version int, computedAt time.Time, rev int, regions []byte, err error) {
	var payload []byte
	var status string
	err = s.PG.QueryRow(ctx, `SELECT version, status, computed_at, network_revision, payload FROM serviceability_snapshots ORDER BY version DESC LIMIT 1`).
		Scan(&version, &status, &computedAt, &rev, &payload)
	if err == pgx.ErrNoRows {
		return 1, time.Now().UTC(), 1, []byte(`{"regions":[]}`), nil
	}
	return version, computedAt, rev, payload, err
}

func (s *Store) PublishSnapshot(ctx context.Context, version, rev int, payload []byte) error {
	_, err := s.PG.Exec(ctx, `INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, payload) VALUES ($1,'complete',now(),$2,$3)`, version, rev, payload)
	return err
}

func (s *Store) NextServiceabilityVersion(ctx context.Context) (int, error) {
	var n int
	err := s.PG.QueryRow(ctx, `SELECT COALESCE(max(version),0)+1 FROM serviceability_snapshots`).Scan(&n)
	return n, err
}
"}

{"path":"/workspace/backend/http.go","command":"create","file_text":"package main

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strings"
	"time"

	"github.com/google/uuid"
)

type ctxKey int

const authKey ctxKey = 1

func getAuth(r *http.Request) *AuthContext {
	v, _ := r.Context().Value(authKey).(*AuthContext)
	return v
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, data any) {
	writeJSON(w, status, map[string]any{"data": data})
}

func writeErr(w http.ResponseWriter, status int, code, msg string) {
	if msg == "" {
		msg = code
	}
	writeJSON(w, status, APIError{Error: msg, Code: code})
}

func decodeJSON(r *http.Request, dst any) error {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return err
	}
	return nil
}

func parseTime(s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, errors.New("empty time")
	}
	if t, err := time.Parse(time.RFC3339, s); err == nil {
		return t, nil
	}
	if t, err := time.Parse(time.RFC3339Nano, s); err == nil {
		return t, nil
	}
	return time.Time{}, errors.New("invalid time")
}

func parseUUID(s string) (uuid.UUID, error) {
	return uuid.Parse(s)
}

func randomToken() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

func hashBytes(b []byte) string {
	h := sha256.Sum256(b)
	return hex.EncodeToString(h[:])
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(strings.ToLower(h), "bearer ") {
		return strings.TrimSpace(h[7:])
	}
	return ""
}

func (app *App) withAuth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		tok := bearerToken(r)
		if tok == "" {
			writeErr(w, 401, "unauthorized", "missing token")
			return
		}
		sess, err := app.Store.GetSession(r.Context(), tok)
		if err != nil || sess == nil || time.Now().After(sess.ExpiresAt) {
			writeErr(w, 401, "unauthorized", "invalid token")
			return
		}
		u, err := app.Store.GetUserByID(r.Context(), sess.UserID)
		if err != nil || u == nil || !u.Active {
			writeErr(w, 401, "unauthorized", "invalid user")
			return
		}
		auth := &AuthContext{User: *u, Session: *sess, ActiveRole: sess.ActiveRole}
		ctx := context.WithValue(r.Context(), authKey, auth)
		next(w, r.WithContext(ctx))
	}
}

func requireRole(auth *AuthContext, roles ...string) bool {
	if auth == nil {
		return false
	}
	if auth.ActiveRole == "" {
		return false
	}
	for _, role := range roles {
		if auth.ActiveRole == role {
			return true
		}
	}
	return false
}

func roleSelected(auth *AuthContext) bool {
	return auth != nil && auth.ActiveRole != "" && containsString(auth.User.Roles, auth.ActiveRole)
}

func adminOrDispatcher(auth *AuthContext) bool {
	return requireRole(auth, RoleAdministrator, RoleDispatcher)
}

type captured struct {
	http.ResponseWriter
	status int
	buf    []byte
}

func (c *captured) WriteHeader(code int) {
	c.status = code
	c.ResponseWriter.WriteHeader(code)
}

func (c *captured) Write(b []byte) (int, error) {
	c.buf = append(c.buf, b...)
	return c.ResponseWriter.Write(b)
}

func (app *App) withIdempotency(endpoint string, next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		auth := getAuth(r)
		body, err := io.ReadAll(r.Body)
		if err != nil {
			writeErr(w, 400, "invalid_json", "invalid json")
			return
		}
		r.Body = io.NopCloser(strings.NewReader(string(body)))

		var peek map[string]any
		_ = json.Unmarshal(body, &peek)
		key, _ := peek["idempotencyKey"].(string)
		if key == "" {
			writeErr(w, 400, "idempotency_required", "idempotencyKey is required")
			return
		}
		h := hashBytes(body)
		if auth != nil {
			storedHash, status, storedBody, ok, err := app.Store.GetIdempotency(r.Context(), key, auth.User.ID, endpoint)
			if err == nil && ok {
				if storedHash != h {
					writeErr(w, 409, "idempotency_conflict", "idempotency key reused with different request")
					return
				}
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(status)
				_, _ = w.Write(storedBody)
				return
			}
		}
		cw := &captured{ResponseWriter: w, status: 200}
		next(cw, r)
		if auth != nil && cw.status < 500 {
			_ = app.Store.PutIdempotency(r.Context(), key, auth.User.ID, endpoint, h, cw.status, cw.buf)
		}
	}
}

func validCoord(c Coordinate) bool {
	return c.Latitude >= -90 && c.Latitude <= 90 && c.Longitude >= -180 && c.Longitude <= 180
}

func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	toRad := func(d float64) float64 { return d * 3.141592653589793 / 180 }
	dLat := toRad(lat2 - lat1)
	dLng := toRad(lng2 - lng1)
	a := sin(dLat/2)*sin(dLat/2) + cos(toRad(lat1))*cos(toRad(lat2))*sin(dLng/2)*sin(dLng/2)
	return 2 * R * asin(minF(1, sqrt(a)))
}

func sin(x float64) float64 {
	// use math
	return mathSin(x)
}

func cos(x float64) float64  { return mathCos(x) }
func asin(x float64) float64 { return mathAsin(x) }
func sqrt(x float64) float64 { return mathSqrt(x) }
func minF(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
"}

