{"path":"/workspace/backend/planning.go","command":"create","file_text":"package main

import (
	"context"
	"fmt"
	"math"
	"sort"
	"time"

	"github.com/google/uuid"
)

type RouteHop struct {
	From         uuid.UUID
	To           uuid.UUID
	ConnectionID uuid.UUID
	Minutes      int
	Cost         float64
	Cooled       bool
}

type PlannedRoute struct {
	CollectionPoint uuid.UUID
	Laboratory      uuid.UUID
	Hops            []RouteHop
	Nodes           []uuid.UUID // path including collection point and lab
	TotalMinutes    int
	TotalCost       float64
	NeedsCooled     bool
}

type ServiceabilityResult struct {
	Serviceable           bool
	Reason                string
	TargetLaboratoryID    *uuid.UUID
	EstimatedArrivalAt    *time.Time
	ServiceabilityVersion int
	Route                 *PlannedRoute
	CollectionPoint       *Location
}

func (app *App) computeServiceability(ctx context.Context, origin Coordinate, originType string, originNodeID *uuid.UUID, sampleTypeID uuid.UUID, requestedAt, deadline time.Time, earliest, latest time.Time, cooledRequired bool) (ServiceabilityResult, error) {
	ver, _, _, _, _ := app.Store.CurrentSnapshot(ctx)
	res := ServiceabilityResult{Serviceable: false, Reason: "no_route", ServiceabilityVersion: ver}

	st, err := app.Store.GetSampleType(ctx, sampleTypeID)
	if err != nil {
		return res, err
	}
	if st == nil {
		res.Reason = "handling_rules_unsatisfiable"
		return res, nil
	}
	if cooledRequired || st.RequiresCooledRoute {
		cooledRequired = true
	}

	locs, err := app.Store.ListLocations(ctx)
	if err != nil {
		return res, err
	}
	conns, err := app.Store.ListConnections(ctx)
	if err != nil {
		return res, err
	}

	// Find collection points covering origin
	var cps []Location
	if originType == OriginNode && originNodeID != nil {
		for _, l := range locs {
			if l.ID == *originNodeID && l.Active {
				cps = append(cps, l)
			}
		}
	} else {
		for _, l := range locs {
			if !l.Active || !l.Functions.CollectionPoint {
				continue
			}
			d := haversineKm(origin.Latitude, origin.Longitude, l.Latitude, l.Longitude)
			cov := l.CoverageKm
			if cov <= 0 {
				cov = 5
			}
			if cov > 5 {
				cov = 5
			}
			if d <= cov+1e-9 {
				cps = append(cps, l)
			}
		}
	}
	if len(cps) == 0 {
		res.Reason = "outside_service_coverage"
		return res, nil
	}

	// accepting labs
	var labs []Location
	for _, l := range locs {
		if !l.Active || !l.Functions.Laboratory {
			continue
		}
		ok, err := app.Store.LabAccepts(ctx, l.ID, sampleTypeID)
		if err != nil {
			return res, err
		}
		if ok {
			labs = append(labs, l)
		}
	}
	if len(labs) == 0 {
		res.Reason = "no_accepting_laboratory"
		return res, nil
	}

	// graph of active connections
	type edge struct {
		to   uuid.UUID
		conn Connection
	}
	adj := map[uuid.UUID][]edge{}
	locByID := map[uuid.UUID]Location{}
	for _, l := range locs {
		locByID[l.ID] = l
	}
	for _, c := range conns {
		if !c.Active {
			continue
		}
		from, ok1 := locByID[c.FromLocationID]
		to, ok2 := locByID[c.ToLocationID]
		if !ok1 || !ok2 || !from.Active || !to.Active {
			continue
		}
		if cooledRequired && !c.Cooled {
			continue
		}
		adj[c.FromLocationID] = append(adj[c.FromLocationID], edge{to: c.ToLocationID, conn: c})
	}

	best := (*PlannedRoute)(nil)
	bestScore := math.MaxFloat64

	for _, cp := range cps {
		for _, lab := range labs {
			route := dijkstra(cp.ID, lab.ID, adj, locByID)
			if route == nil {
				// same node can be both collection and lab
				if cp.ID == lab.ID {
					route = &PlannedRoute{
						CollectionPoint: cp.ID,
						Laboratory:      lab.ID,
						Nodes:           []uuid.UUID{cp.ID},
						NeedsCooled:     cooledRequired,
					}
				} else {
					continue
				}
			}
			// capacity check along path
			if !hasCapacity(route, locByID, cooledRequired) {
				if best == nil {
					res.Reason = "insufficient_capacity"
				}
				continue
			}
			// travel time from origin to CP
			toCP := 0
			if originType != OriginNode || originNodeID == nil || *originNodeID != cp.ID {
				d := haversineKm(origin.Latitude, origin.Longitude, locByID[cp.ID].Latitude, locByID[cp.ID].Longitude)
				toCP = int(math.Ceil(d / 0.4)) // ~24 km/h
				if toCP < 5 {
					toCP = 5
				}
			}
			handling := locByID[cp.ID].HandlingMinutes
			for _, n := range route.Nodes {
				if n == cp.ID {
					continue
				}
				handling += locByID[n].HandlingMinutes
			}
			total := toCP + handling + route.TotalMinutes
			eta := requestedAt.Add(time.Duration(total) * time.Minute)
			if earliest.After(requestedAt) {
				eta = earliest.Add(time.Duration(total) * time.Minute)
			}
			if eta.After(deadline) {
				if best == nil && res.Reason != "insufficient_capacity" {
					res.Reason = "deadline_unreachable"
				}
				continue
			}
			score := float64(total) + route.TotalCost
			if score < bestScore {
				bestScore = score
				cpCopy := cp
				labID := lab.ID
				r := *route
				r.CollectionPoint = cp.ID
				r.Laboratory = lab.ID
				r.NeedsCooled = cooledRequired
				best = &r
				res.Serviceable = true
				res.Reason = "serviceable"
				res.TargetLaboratoryID = &labID
				res.EstimatedArrivalAt = &eta
				res.Route = best
				res.CollectionPoint = &cpCopy
			}
		}
	}
	if best == nil && res.Reason == "no_route" {
		// leave as no_route
	}
	return res, nil
}

func hasCapacity(route *PlannedRoute, locByID map[uuid.UUID]Location, cooled bool) bool {
	for _, n := range route.Nodes {
		l := locByID[n]
		if cooled {
			if l.CooledCapacity > 0 && l.CooledCapacity-l.CooledReserved < 1 {
				return false
			}
		} else {
			if l.CapacityUnits > 0 && l.CapacityUnits-l.ReservedUnits < 1 {
				return false
			}
		}
	}
	// connections checked via hops if capacity configured
	return true
}

func dijkstra(src, dst uuid.UUID, adj map[uuid.UUID][]struct {
	to   uuid.UUID
	conn Connection
}, locByID map[uuid.UUID]Location) *PlannedRoute {
	type item struct {
		id    uuid.UUID
		cost  float64
		mins  int
		prev  uuid.UUID
		via   *Connection
		hasP  bool
	}
	dist := map[uuid.UUID]float64{src: 0}
	prev := map[uuid.UUID]uuid.UUID{}
	via := map[uuid.UUID]Connection{}
	mins := map[uuid.UUID]int{src: 0}
	visited := map[uuid.UUID]bool{}

	for {
		var best uuid.UUID
		bestC := math.MaxFloat64
		found := false
		for id, c := range dist {
			if visited[id] {
				continue
			}
			if c < bestC {
				bestC = c
				best = id
				found = true
			}
		}
		if !found {
			break
		}
		if best == dst {
			break
		}
		visited[best] = true
		for _, e := range adj[best] {
			nc := bestC + e.conn.CostUnits + float64(e.conn.TravelMinutes)*0.01
			old, ok := dist[e.to]
			if !ok || nc < old {
				dist[e.to] = nc
				prev[e.to] = best
				via[e.to] = e.conn
				mins[e.to] = mins[best] + e.conn.TravelMinutes
			}
		}
	}
	if _, ok := dist[dst]; !ok && src != dst {
		return nil
	}
	if src == dst {
		return &PlannedRoute{CollectionPoint: src, Laboratory: dst, Nodes: []uuid.UUID{src}}
	}
	var hops []RouteHop
	var nodes []uuid.UUID
	cur := dst
	for cur != src {
		p, ok := prev[cur]
		if !ok {
			return nil
		}
		c := via[cur]
		hops = append([]RouteHop{{From: p, To: cur, ConnectionID: c.ID, Minutes: c.TravelMinutes, Cost: c.CostUnits, Cooled: c.Cooled}}, hops...)
		nodes = append([]uuid.UUID{cur}, nodes...)
		cur = p
	}
	nodes = append([]uuid.UUID{src}, nodes...)
	totalM, totalC := 0, 0.0
	for _, h := range hops {
		totalM += h.Minutes
		totalC += h.Cost
	}
	return &PlannedRoute{CollectionPoint: src, Laboratory: dst, Hops: hops, Nodes: nodes, TotalMinutes: totalM, TotalCost: totalC}
}

func (app *App) materializeJourney(ctx context.Context, sm *Sample, st *SampleType, res ServiceabilityResult, presealed bool, actorID, role string) (*Journey, []Assignment, error) {
	if res.Route == nil {
		return nil, nil, fmt.Errorf("no route")
	}
	route := res.Route
	now := time.Now().UTC()
	jid := uuid.New()
	mode := RouteDirect
	if len(route.Hops) > 1 {
		mode = RouteMultiStop
	}
	j := Journey{
		ID:                  jid,
		PlanVersion:         1,
		RouteMode:           mode,
		Status:              StatusPlanned,
		EstimatedDeliveryAt: res.EstimatedArrivalAt,
		TotalCostUnits:      route.TotalCost,
		CapacityUsed:        1,
		Valid:               true,
	}
	if err := app.Store.InsertJourney(ctx, j); err != nil {
		return nil, nil, err
	}
	if err := app.Store.AddJourneySample(ctx, jid, sm.ID); err != nil {
		return nil, nil, err
	}

	// reserve capacity
	cooled := route.NeedsCooled
	for _, n := range route.Nodes {
		loc, _ := app.Store.GetLocation(ctx, n)
		if loc == nil {
			continue
		}
		need := false
		if cooled {
			need = loc.CooledCapacity > 0
		} else {
			need = loc.CapacityUnits > 0
		}
		if need {
			if err := app.Store.ReserveCapacity(ctx, "location", n, sm.ID, jid, cooled, 1); err != nil {
				return nil, nil, err
			}
		}
	}
	for _, h := range route.Hops {
		c, _ := app.Store.GetConnection(ctx, h.ConnectionID)
		if c == nil {
			continue
		}
		need := false
		if cooled {
			need = c.CooledCapacity > 0
		} else {
			need = c.CapacityUnits > 0
		}
		if need {
			if err := app.Store.ReserveCapacity(ctx, "connection", h.ConnectionID, sm.ID, jid, cooled, 1); err != nil {
				return nil, nil, err
			}
		}
	}

	// stops
	seq := 1
	est := sm.RequestedAt
	if sm.EarliestCollectionAt.After(est) {
		est = sm.EarliestCollectionAt
	}
	// pickup
	pickupLoc := route.CollectionPoint
	plat, plng := sm.OriginLat, sm.OriginLng
	_ = app.Store.InsertStop(ctx, uuid.New(), jid, &pickupLoc, StopPickup, seq, est, 0, &plat, &plng)
	seq++

	// intermediate + delivery
	for i, node := range route.Nodes {
		loc, _ := app.Store.GetLocation(ctx, node)
		if loc == nil {
			continue
		}
		est = est.Add(time.Duration(loc.HandlingMinutes) * time.Minute)
		if i < len(route.Hops) {
			est = est.Add(time.Duration(route.Hops[i].Minutes) * time.Minute)
		}
		lat, lng := loc.Latitude, loc.Longitude
		stType := StopHandoff
		if node == route.Laboratory {
			stType = StopDelivery
		}
		_ = app.Store.InsertStop(ctx, uuid.New(), jid, &node, stType, seq, est, loc.HandlingMinutes, &lat, &lng)
		seq++
	}

	var asgs []Assignment
	aSeq := 1

	// collection assignment if not presealed and origin is home (or clinic needing collection)
	if !presealed && sm.OriginType == OriginHome {
		a := Assignment{
			ID: uuid.New(), JourneyID: jid, SampleID: sm.ID, Kind: KindCollection,
			Sequence: aSeq, Status: StatusPending, ToLocationID: &route.CollectionPoint,
		}
		asgs = append(asgs, a)
		aSeq++
	}

	// node assignments at intermediate transfer/hub (not first if that's just CP pickup, not last lab)
	for i, node := range route.Nodes {
		loc, _ := app.Store.GetLocation(ctx, node)
		if loc == nil {
			continue
		}
		isLab := node == route.Laboratory
		isFirst := i == 0
		if isLab {
			continue
		}
		if isFirst && sm.OriginType == OriginHome && !presealed {
			// collection point receiving from home — still a node assignment
		}
		if loc.Functions.TransferPoint || loc.Functions.Hub || loc.Functions.CollectionPoint {
			nid := node
			var from, to *uuid.UUID
			if i > 0 {
				f := route.Nodes[i-1]
				from = &f
			}
			if i+1 < len(route.Nodes) {
				t := route.Nodes[i+1]
				to = &t
			}
			a := Assignment{
				ID: uuid.New(), JourneyID: jid, SampleID: sm.ID, Kind: KindNode,
				Sequence: aSeq, Status: StatusPending, NodeID: &nid,
				FromLocationID: from, ToLocationID: to,
			}
			asgs = append(asgs, a)
			aSeq++
		}
	}

	// transport legs
	for _, h := range route.Hops {
		from, to := h.From, h.To
		a := Assignment{
			ID: uuid.New(), JourneyID: jid, SampleID: sm.ID, Kind: KindTransport,
			Sequence: aSeq, Status: StatusPending, FromLocationID: &from, ToLocationID: &to,
		}
		asgs = append(asgs, a)
		aSeq++
	}

	// laboratory assignment
	labID := route.Laboratory
	a := Assignment{
		ID: uuid.New(), JourneyID: jid, SampleID: sm.ID, Kind: KindLaboratory,
		Sequence: aSeq, Status: StatusPending, LaboratoryID: &labID, ToLocationID: &labID,
	}
	asgs = append(asgs, a)

	for i := range asgs {
		if err := app.Store.InsertAssignment(ctx, asgs[i]); err != nil {
			return nil, nil, err
		}
	}

	// offer first actionable assignment
	if err := app.offerNext(ctx, sm, asgs, st); err != nil {
		return nil, nil, err
	}

	sm.ActiveJourneyID = &jid
	sm.TargetLaboratoryID = &route.Laboratory
	if presealed {
		sm.Sealed = true
		t := now
		sm.SealedAt = &t
		sm.Status = StatusSealed
		sm.CurrentHolderID = &sm.RequesterID // will be overwritten by registrar
	} else {
		sm.Status = StatusRequested
	}
	if err := app.Store.UpdateSample(ctx, *sm); err != nil {
		return nil, nil, err
	}

	_, _ = app.Store.AddTimeline(ctx, "journey_created", actorID, role, "sample", sm.ID.String(), true, map[string]interface{}{
		"journeyId": jid.String(),
	})
	_, _ = app.Store.AddRealtime(ctx, "journey.created", "journey", jid.String(), map[string]interface{}{"sampleId": sm.ID.String()})
	return &j, asgs, nil
}

func (app *App) offerNext(ctx context.Context, sm *Sample, asgs []Assignment, st *SampleType) error {
	// find first pending assignment that is ready (prior completed or first)
	sort.Slice(asgs, func(i, j int) bool { return asgs[i].Sequence < asgs[j].Sequence })
	for i := range asgs {
		a := &asgs[i]
		if a.Status != StatusPending {
			continue
		}
		// skip if already offered and not expired
		if a.OfferedTo != nil && a.OfferExpiresAt != nil && a.OfferExpiresAt.After(time.Now()) {
			return nil
		}
		// prior must be completed or accepted for collection? collection can start first
		if i > 0 {
			prevDone := asgs[i-1].Status == StatusCompleted
			// allow offering next after previous accepted for pipeline, but typically after complete
			if !prevDone && asgs[i-1].Status != StatusAccepted && asgs[i-1].Status != StatusInProgress {
				// still offer collection first only
				if a.Kind != KindCollection {
					continue
				}
			}
		}
		worker, err := app.pickWorker(ctx, *a, st)
		if err != nil {
			return err
		}
		if worker == nil {
			// leave pending unoffered; exception later
			return nil
		}
		exp := time.Now().UTC().Add(OfferTimeout)
		a.OfferedTo = &worker.ID
		a.OfferExpiresAt = &exp
		if err := app.Store.UpdateAssignment(ctx, *a); err != nil {
			return err
		}
		_ = app.Store.MarkOffered(ctx, worker.ID)
		_, _ = app.Store.AddTimeline(ctx, "assignment_offered", "system", "system", "assignment", a.ID.String(), true, map[string]interface{}{
			"workerId": worker.ID.String(), "kind": a.Kind,
		})
		_, _ = app.Store.AddRealtime(ctx, "assignment.offered", "assignment", a.ID.String(), map[string]interface{}{
			"workerId": worker.ID.String(),
		})
		if sm.Status == StatusRequested {
			sm.Status = StatusOffered
			_ = app.Store.UpdateSample(ctx, *sm)
		}
		return nil
	}
	return nil
}

func (app *App) pickWorker(ctx context.Context, a Assignment, st *SampleType) (*User, error) {
	users, err := app.Store.ListUsers(ctx)
	if err != nil {
		return nil, err
	}
	type cand struct {
		u     User
		load  int
		score int
	}
	var cs []cand
	now := time.Now().UTC()
	for _, u := range users {
		if !u.Active || !u.Available {
			continue
		}
		switch a.Kind {
		case KindCollection:
			if !containsString(u.Roles, RoleCollectionProfessional) {
				continue
			}
			if st != nil && st.QualifiedCollectorRequired {
				ok := false
				certs, _ := app.Store.GetCertifications(ctx, u.ID)
				for _, c := range certs {
					if c.Active && c.Code == st.RequiredQualification {
						if c.ExpiresAt == nil || *c.ExpiresAt == "" {
							ok = true
							break
						}
						t, err := time.Parse(time.RFC3339, *c.ExpiresAt)
						if err == nil && t.After(now) {
							ok = true
							break
						}
					}
				}
				if !ok && containsString(u.Qualifications, st.RequiredQualification) {
					ok = true
				}
				if !ok {
					continue
				}
			}
		case KindTransport:
			if !containsString(u.Roles, RoleDeliveryPartner) {
				continue
			}
		case KindNode:
			if !containsString(u.Roles, RoleNodeHandler) {
				continue
			}
			if a.NodeID != nil && (u.AssignedLocationID == nil || *u.AssignedLocationID != *a.NodeID) {
				continue
			}
		case KindLaboratory:
			if !containsString(u.Roles, RoleLaboratoryTeam) {
				continue
			}
			if a.LaboratoryID != nil && (u.AssignedLocationID == nil || *u.AssignedLocationID != *a.LaboratoryID) {
				continue
			}
		default:
			continue
		}
		asgs, _ := app.Store.ListAssignmentsForWorker(ctx, u.ID)
		load := 0
		for _, x := range asgs {
			if x.Status == StatusAccepted || x.Status == StatusInProgress || x.Status == StatusPending {
				load++
			}
		}
		score := load * 10
		if u.DeclineWindowStart != nil && now.Sub(*u.DeclineWindowStart) < DeclinePenalty {
			score += u.DeclineCount * 5
		}
		if u.LastOfferedAt != nil {
			// prefer those not recently offered
			mins := int(now.Sub(*u.LastOfferedAt).Minutes())
			if mins < 30 {
				score += (30 - mins)
			}
		}
		cs = append(cs, cand{u: u, load: load, score: score})
	}
	if len(cs) == 0 {
		return nil, nil
	}
	sort.Slice(cs, func(i, j int) bool {
		if cs[i].score != cs[j].score {
			return cs[i].score < cs[j].score
		}
		return cs[i].u.Username < cs[j].u.Username
	})
	return &cs[0].u, nil
}

func (app *App) rebuildServiceabilitySnapshot(ctx context.Context) {
	app.snapMu.Lock()
	defer app.snapMu.Unlock()
	locs, err := app.Store.ListLocations(ctx)
	if err != nil {
		return
	}
	type region struct {
		LocationID string  `json:"locationId"`
		Name       string  `json:"name"`
		Latitude   float64 `json:"latitude"`
		Longitude  float64 `json:"longitude"`
		CoverageKm float64 `json:"coverageKm"`
	}
	var regions []region
	count := 0
	for _, l := range locs {
		if l.Active && l.Functions.CollectionPoint {
			cov := l.CoverageKm
			if cov <= 0 {
				cov = 5
			}
			if cov > 5 {
				cov = 5
			}
			regions = append(regions, region{
				LocationID: l.ID.String(), Name: l.Name,
				Latitude: l.Latitude, Longitude: l.Longitude, CoverageKm: cov,
			})
			count++
		}
	}
	if regions == nil {
		regions = []region{}
	}
	payload, _ := jsonMarshal(map[string]any{"regions": regions, "activeCollectionPointCount": count})
	rev, _ := app.Store.NetworkRevision(ctx)
	ver, _ := app.Store.NextServiceabilityVersion(ctx)
	_ = app.Store.PublishSnapshot(ctx, ver, rev, payload)
}

func jsonMarshal(v any) ([]byte, error) {
	return jsonBytes(v)
}
"}

