{"path":"/workspace/backend/audit.go","command":"create","file_text":"package main

import (
	"context"
	"strings"
	"time"

	"github.com/google/uuid"
	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

func (app *App) writeAudit(ctx context.Context, actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	now := time.Now().UTC()
	id := uuid.New().String()
	doc := bson.M{
		"auditId":    id,
		"audit_id":   id,
		"actorId":    actorID,
		"actor_id":   actorID,
		"role":       role,
		"actorRole":  role,
		"action":     action,
		"entityType": entityType,
		"entity_type": entityType,
		"entityId":   entityID,
		"entity_id":  entityID,
		"success":    success,
		"occurredAt": now,
		"occurred_at": now,
		"details":    details,
	}
	_, _ = app.Store.Audit.InsertOne(ctx, doc)
	_, _ = app.Store.AddTimeline(ctx, action, actorID, role, entityType, entityID, success, details)
}

type AuditQuery struct {
	Query      string
	ActorID    string
	EntityType string
	EntityID   string
	Action     string
	Role       string
	Success    *bool
	FromTime   *time.Time
	ToTime     *time.Time
	Limit      int
	Offset     int
	Order      string
}

func (app *App) searchAudit(ctx context.Context, q AuditQuery) ([]map[string]any, int, error) {
	filter := bson.M{}
	if q.ActorID != "" {
		filter["actorId"] = q.ActorID
	}
	if q.EntityType != "" {
		filter["entityType"] = q.EntityType
	}
	if q.EntityID != "" {
		filter["entityId"] = q.EntityID
	}
	if q.Action != "" {
		filter["action"] = q.Action
	}
	if q.Role != "" {
		filter["role"] = q.Role
	}
	if q.Success != nil {
		filter["success"] = *q.Success
	}
	if q.FromTime != nil || q.ToTime != nil {
		rng := bson.M{}
		if q.FromTime != nil {
			rng["$gte"] = *q.FromTime
		}
		if q.ToTime != nil {
			rng["$lte"] = *q.ToTime
		}
		filter["occurredAt"] = rng
	}
	if q.Query != "" {
		// text-ish match across a few fields
		rx := bson.M{"$regex": q.Query, "$options": "i"}
		filter["$or"] = []bson.M{
			{"action": rx},
			{"entityType": rx},
			{"entityId": rx},
			{"actorId": rx},
			{"role": rx},
		}
	}
	total, err := app.Store.Audit.CountDocuments(ctx, filter)
	if err != nil {
		return nil, 0, err
	}
	sortDir := -1
	if q.Order == "oldest_first" {
		sortDir = 1
	}
	opts := options.Find().SetSort(bson.D{{Key: "occurredAt", Value: sortDir}}).SetSkip(int64(q.Offset)).SetLimit(int64(q.Limit))
	cur, err := app.Store.Audit.Find(ctx, filter, opts)
	if err != nil {
		return nil, 0, err
	}
	defer cur.Close(ctx)
	var entries []map[string]any
	for cur.Next(ctx) {
		var raw bson.M
		if err := cur.Decode(&raw); err != nil {
			continue
		}
		entries = append(entries, normalizeAudit(raw))
	}
	if entries == nil {
		entries = []map[string]any{}
	}
	_ = strings.TrimSpace
	return entries, int(total), nil
}

func normalizeAudit(raw bson.M) map[string]any {
	str := func(keys ...string) string {
		for _, k := range keys {
			if v, ok := raw[k]; ok && v != nil {
				switch t := v.(type) {
				case string:
					return t
				}
			}
		}
		return ""
	}
	occurred := ""
	for _, k := range []string{"occurredAt", "occurred_at"} {
		if v, ok := raw[k]; ok {
			switch t := v.(type) {
			case time.Time:
				occurred = fmtTime(t)
			case bson.DateTime:
				occurred = fmtTime(t.Time())
			}
		}
	}
	success, _ := raw["success"].(bool)
	details := map[string]any{}
	if d, ok := raw["details"].(bson.M); ok {
		for k, v := range d {
			details[k] = v
		}
	} else if d, ok := raw["details"].(map[string]any); ok {
		details = d
	}
	id := str("auditId", "audit_id")
	actor := str("actorId", "actor_id")
	role := str("role", "actorRole")
	return map[string]any{
		"auditId":    id,
		"audit_id":   id,
		"actorId":    actor,
		"actor_id":   actor,
		"role":       role,
		"actorRole":  role,
		"action":     str("action"),
		"entityType": str("entityType", "entity_type"),
		"entity_type": str("entityType", "entity_type"),
		"entityId":   str("entityId", "entity_id"),
		"entity_id":  str("entityId", "entity_id"),
		"success":    success,
		"occurredAt": occurred,
		"occurred_at": occurred,
		"details":    details,
	}
}
"}

{"path":"/workspace/backend/main.go","command":"create","file_text":"package main

import (
	"context"
	"io/fs"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/google/uuid"
	"golang.org/x/crypto/bcrypt"
)

type App struct {
	Store  *Store
	snapMu sync.Mutex
}

func main() {
	ctx := context.Background()
	store, err := Connect(ctx)
	if err != nil {
		log.Fatalf("connect: %v", err)
	}
	defer store.Close()

	schema, err := os.ReadFile(findSchema())
	if err != nil {
		log.Fatalf("schema: %v", err)
	}
	// Ensure schema exists (idempotent CREATE IF NOT EXISTS)
	if err := store.ApplySchema(ctx, string(schema)); err != nil {
		log.Fatalf("apply schema: %v", err)
	}
	if err := store.MaterializeMongo(ctx); err != nil {
		log.Fatalf("mongo: %v", err)
	}
	// seed sample types if empty
	types, _ := store.ListSampleTypes(ctx)
	if len(types) == 0 {
		if err := seedDefaultSampleTypes(ctx, store); err != nil {
			log.Fatalf("seed types: %v", err)
		}
	}

	app := &App{Store: store}
	if err := app.ensureAdmin(ctx); err != nil {
		log.Fatalf("admin: %v", err)
	}
	app.rebuildServiceabilitySnapshot(ctx)

	go app.offerLoop()

	mux := http.NewServeMux()
	app.routes(mux)

	addr := "127.0.0.1:8080"
	if p := os.Getenv("LISTEN_ADDR"); p != "" {
		addr = p
	}
	log.Printf("listening on http://%s", addr)
	if err := http.ListenAndServe(addr, cors(mux)); err != nil {
		log.Fatal(err)
	}
}

func findSchema() string {
	cands := []string{
		"schema.sql",
		"backend/schema.sql",
		"/workspace/backend/schema.sql",
	}
	if exe, err := os.Executable(); err == nil {
		cands = append([]string{filepath.Join(filepath.Dir(exe), "schema.sql")}, cands...)
	}
	for _, c := range cands {
		if _, err := os.Stat(c); err == nil {
			return c
		}
	}
	return "schema.sql"
}

func (app *App) ensureAdmin(ctx context.Context) error {
	n, err := app.Store.CountUsers(ctx)
	if err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	user := os.Getenv("ADMIN_USERNAME")
	pass := os.Getenv("ADMIN_PASSWORD")
	if user == "" || pass == "" {
		log.Printf("no users and ADMIN_USERNAME/ADMIN_PASSWORD not set; waiting for first start with credentials")
		return nil
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(pass), bcrypt.DefaultCost)
	if err != nil {
		return err
	}
	u := User{
		ID: uuid.New(), Username: user, PasswordHash: string(hash),
		FullName: "Administrator", Roles: []string{RoleAdministrator},
		Active: true, Available: true, CapacityUnits: 0,
	}
	if err := app.Store.InsertUser(ctx, u); err != nil {
		return err
	}
	log.Printf("created initial administrator %s", user)
	return nil
}

func (app *App) offerLoop() {
	t := time.NewTicker(15 * time.Second)
	defer t.Stop()
	for range t.C {
		ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
		app.expireAndReoffer(ctx)
		cancel()
	}
}

func (app *App) expireAndReoffer(ctx context.Context) {
	asgs, err := app.Store.ListOpenOffered(ctx)
	if err != nil {
		return
	}
	now := time.Now().UTC()
	for _, a := range asgs {
		if a.OfferExpiresAt != nil && now.After(*a.OfferExpiresAt) {
			if a.OfferedTo != nil {
				_ = app.Store.BumpDecline(ctx, *a.OfferedTo)
			}
			a.OfferedTo = nil
			a.OfferExpiresAt = nil
			_ = app.Store.UpdateAssignment(ctx, a)
			sm, _ := app.Store.GetSample(ctx, a.SampleID)
			if sm == nil {
				continue
			}
			st, _ := app.Store.GetSampleType(ctx, sm.SampleTypeID)
			all, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
			_ = app.offerNext(ctx, sm, all, st)
			// if still no worker after long time, exception
			if sm.CreatedAtZero() {
				continue
			}
		}
	}
	// flag samples with unoffered required assignments for too long
	samples, _ := app.Store.ListSamples(ctx)
	for _, sm := range samples {
		if sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired || sm.Status == StatusException || sm.Status == StatusUnserviceable {
			continue
		}
		asgs, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
		for _, a := range asgs {
			if a.Status == StatusPending && a.OfferedTo == nil && a.Kind == KindCollection {
				// created long ago?
				st, _ := app.Store.GetSampleType(ctx, sm.SampleTypeID)
				if st != nil && st.QualifiedCollectorRequired {
					// try offer again
					_ = app.offerNext(ctx, &sm, asgs, st)
					// if still none, check age via first timeline? use requested_at
					if time.Since(sm.RequestedAt) > NoWorkerTimeout {
						sm.Status = StatusException
						sm.Exception = map[string]interface{}{"reason": "no_qualified_worker", "assignmentId": a.ID.String()}
						_ = app.Store.UpdateSample(ctx, sm)
						app.writeAudit(ctx, "system", "system", "exception", "sample", sm.ID.String(), true, sm.Exception)
					}
				}
			}
		}
	}
}

