func (app *App) handleReady(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 3*time.Second)
	defer cancel()
	if app.Store.Ready(ctx) {
		writeJSON(w, 200, map[string]string{"status": "ready"})
		return
	}
	writeJSON(w, 503, map[string]string{"status": "starting"})
}

func (app *App) handleLogin(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	u, err := app.Store.GetUserByUsername(r.Context(), req.Username)
	if err != nil || u == nil || !u.Active {
		writeErr(w, 401, "invalid_credentials", "invalid credentials")
		return
	}
	if bcrypt.CompareHashAndPassword([]byte(u.PasswordHash), []byte(req.Password)) != nil {
		writeErr(w, 401, "invalid_credentials", "invalid credentials")
		return
	}
	role := ""
	if len(u.Roles) == 1 {
		role = u.Roles[0]
	}
	tok := randomToken()
	sess := Session{Token: tok, UserID: u.ID, ActiveRole: role, ExpiresAt: time.Now().Add(24 * time.Hour)}
	if err := app.Store.CreateSession(r.Context(), sess); err != nil {
		writeErr(w, 500, "internal_error", "session")
		return
	}
	app.writeAudit(r.Context(), u.ID.String(), role, "sign_in", "user", u.ID.String(), true, map[string]interface{}{"username": u.Username})
	writeData(w, 200, map[string]any{
		"sessionToken": tok,
		"userId":       u.ID.String(),
		"roles":        u.Roles,
		"activeRole":   role,
	})
}

func (app *App) handleSelectRole(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	var req struct {
		Role string `json:"role"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if !validRole(req.Role) {
		writeErr(w, 400, "invalid_role", "invalid role")
		return
	}
	if !containsString(auth.User.Roles, req.Role) {
		writeErr(w, 403, "role_not_held", "role not held")
		return
	}
	if err := app.Store.SetActiveRole(r.Context(), auth.Session.Token, req.Role); err != nil {
		writeErr(w, 500, "internal_error", "update role")
		return
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), req.Role, "select_role", "user", auth.User.ID.String(), true, map[string]interface{}{"role": req.Role})
	writeData(w, 200, map[string]any{"activeRole": req.Role, "roles": auth.User.Roles})
}

func (app *App) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !requireRole(auth, RoleAdministrator) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		Username           string          `json:"username"`
		InitialPassword    string          `json:"initialPassword"`
		Email              string          `json:"email"`
		FullName           string          `json:"fullName"`
		Phone              string          `json:"phone"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             bool            `json:"active"`
		AssignedLocationID *string         `json:"assignedLocationId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Username == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
		writeErr(w, 400, "invalid_user", "invalid user")
		return
	}
	for _, role := range req.Roles {
		if !validRole(role) {
			writeErr(w, 400, "invalid_user", "invalid role")
			return
		}
	}
	if existing, _ := app.Store.GetUserByUsername(r.Context(), req.Username); existing != nil {
		writeErr(w, 409, "username_exists", "username exists")
		return
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(req.InitialPassword), bcrypt.DefaultCost)
	if err != nil {
		writeErr(w, 500, "internal_error", "hash")
		return
	}
	var loc *uuid.UUID
	if req.AssignedLocationID != nil && *req.AssignedLocationID != "" {
		id, err := uuid.Parse(*req.AssignedLocationID)
		if err != nil {
			writeErr(w, 400, "invalid_user", "invalid assigned location")
			return
		}
		loc = &id
	}
	if req.Qualifications == nil {
		req.Qualifications = []string{}
	}
	if req.Certifications == nil {
		req.Certifications = []Certification{}
	}
	for _, c := range req.Certifications {
		if c.Code == "" {
			writeErr(w, 400, "invalid_certification", "invalid certification")
			return
		}
	}
	u := User{
		ID: uuid.New(), Username: req.Username, PasswordHash: string(hash),
		Email: req.Email, FullName: req.FullName, Phone: req.Phone,
		Roles: req.Roles, Qualifications: req.Qualifications, AssignedLocationID: loc,
		Active: req.Active, Available: true, CapacityUnits: 1,
	}
	if err := app.Store.InsertUser(r.Context(), u); err != nil {
		writeErr(w, 500, "internal_error", "insert user")
		return
	}
	if err := app.Store.ReplaceCertifications(r.Context(), u.ID, req.Certifications); err != nil {
		writeErr(w, 400, "invalid_certification", err.Error())
		return
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "create_user", "user", u.ID.String(), true, map[string]interface{}{"username": u.Username})
	writeData(w, 201, userPayload(u, req.Certifications))
}

func userPayload(u User, certs []Certification) map[string]any {
	if certs == nil {
		certs = []Certification{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	m := map[string]any{
		"userId":          u.ID.String(),
		"username":        u.Username,
		"roles":           u.Roles,
		"qualifications":  u.Qualifications,
		"certifications":  certs,
		"active":          u.Active,
	}
	if u.Email != "" {
		m["email"] = u.Email
	}
	if u.FullName != "" {
		m["fullName"] = u.FullName
	}
	if u.Phone != "" {
		m["phone"] = u.Phone
	}
	return m
}

func (app *App) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
