func (app *App) handleCreateSampleType(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !requireRole(auth, RoleAdministrator) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		Name                       string   `json:"name"`
		QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
		RequiredQualification      string   `json:"requiredQualification"`
		ContainerType              string   `json:"containerType"`
		TemperatureMinC            float64  `json:"temperatureMinC"`
		TemperatureMaxC            float64  `json:"temperatureMaxC"`
		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
		BatchingAllowed            *bool    `json:"batchingAllowed"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Name == "" || req.ContainerType == "" {
		writeErr(w, 400, "invalid_handling_rule", "invalid handling rule")
		return
	}
	if req.TemperatureMinC > req.TemperatureMaxC {
		writeErr(w, 400, "invalid_handling_rule", "invalid temperature range")
		return
	}
	qcr := true
	if req.QualifiedCollectorRequired != nil {
		qcr = *req.QualifiedCollectorRequired
	}
	cooled := false
	if req.RequiresCooledRoute != nil {
		cooled = *req.RequiresCooledRoute
	}
	batch := true
	if req.BatchingAllowed != nil {
		batch = *req.BatchingAllowed
	}
	rq := req.RequiredQualification
	if rq == "" {
		rq = req.Name
	}
	var incomp []uuid.UUID
	for _, s := range req.IncompatibleSampleTypes {
		id, err := uuid.Parse(s)
		if err != nil {
			writeErr(w, 400, "invalid_handling_rule", "invalid incompatible type")
			return
		}
		incomp = append(incomp, id)
	}
	if incomp == nil {
		incomp = []uuid.UUID{}
	}
	st := SampleType{
		ID: uuid.New(), Name: req.Name, QualifiedCollectorRequired: qcr, RequiredQualification: rq,
		ContainerType: req.ContainerType, TemperatureMinC: req.TemperatureMinC, TemperatureMaxC: req.TemperatureMaxC,
		IncompatibleSampleTypes: incomp, RequiresCooledRoute: cooled, BatchingAllowed: batch,
	}
	if err := app.Store.InsertSampleType(r.Context(), st); err != nil {
		writeErr(w, 500, "internal_error", "insert")
		return
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "create_sample_type", "sample_type", st.ID.String(), true, map[string]interface{}{"name": st.Name})
	writeData(w, 201, sampleTypePayload(st))
}

func sampleTypePayload(st SampleType) map[string]any {
	inc := make([]string, 0, len(st.IncompatibleSampleTypes))
	for _, id := range st.IncompatibleSampleTypes {
		inc = append(inc, id.String())
	}
	return map[string]any{
		"sampleTypeId":                 st.ID.String(),
		"name":                         st.Name,
		"qualifiedCollectorRequired":   st.QualifiedCollectorRequired,
		"requiredQualification":        st.RequiredQualification,
		"containerType":                st.ContainerType,
		"temperatureMinC":              st.TemperatureMinC,
		"temperatureMaxC":              st.TemperatureMaxC,
		"incompatibleSampleTypes":      inc,
		"requiresCooledRoute":          st.RequiresCooledRoute,
		"batchingAllowed":              st.BatchingAllowed,
	}
}

