	}
	if req.BatchingAllowed != nil {
		st.BatchingAllowed = *req.BatchingAllowed
	}
	if req.IncompatibleSampleTypes != nil {
		var inc []uuid.UUID
		for _, s := range req.IncompatibleSampleTypes {
			xid, err := uuid.Parse(s)
			if err != nil {
				writeErr(w, 400, "invalid_handling_rule", "invalid incompatible")
				return
			}
			inc = append(inc, xid)
		}
		st.IncompatibleSampleTypes = inc
	}
	if err := app.Store.UpdateSampleType(r.Context(), *st); err != nil {
		writeErr(w, 500, "internal_error", "update")
		return
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "update_sample_type", "sample_type", st.ID.String(), true, nil)
	writeData(w, 201, sampleTypePayload(*st))
}

func parseFunctions(fns []string) (LocationFunctions, bool) {
	var f LocationFunctions
	for _, x := range fns {
		switch x {
		case FnCollectionPoint:
			f.CollectionPoint = true
		case FnTransferPoint:
			f.TransferPoint = true
		case FnHub:
			f.Hub = true
		case FnLaboratory:
			f.Laboratory = true
		default:
			return f, false
		}
	}
	return f, true
}

func locationPayload(l Location) map[string]any {
	return map[string]any{
		"locationId":      l.ID.String(),
		"name":            l.Name,
		"coordinate":      Coordinate{Latitude: l.Latitude, Longitude: l.Longitude},
		"coverageKm":      l.CoverageKm,
		"handlingMinutes": l.HandlingMinutes,
		"active":          l.Active,
		"functions":       l.Functions,
	}
}

func (app *App) handleCreateLocation(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !requireRole(auth, RoleAdministrator) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		Name            string     `json:"name"`
		Coordinate      Coordinate `json:"coordinate"`
		CoverageKm      *float64   `json:"coverageKm"`
		HandlingMinutes *int       `json:"handlingMinutes"`
		Active          bool       `json:"active"`
		Functions       []string   `json:"functions"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Name == "" || !validCoord(req.Coordinate) {
		writeErr(w, 400, "invalid_coordinate", "invalid coordinate")
		return
	}
	cov := 5.0
	if req.CoverageKm != nil {
		cov = *req.CoverageKm
	}
	if cov <= 0 || cov > 5 {
		writeErr(w, 400, "invalid_node_coverage", "coverage must be in (0, 5]")
		return
	}
	hm := 0
	if req.HandlingMinutes != nil {
		hm = *req.HandlingMinutes
	}
	if hm < 0 || hm > 1440 {
		writeErr(w, 400, "invalid_handling_time", "invalid handling time")
		return
	}
	if len(req.Functions) == 0 {
		writeErr(w, 400, "invalid_location_function", "functions required")
		return
	}
	fns, ok := parseFunctions(req.Functions)
	if !ok {
		writeErr(w, 400, "invalid_location_function", "invalid function")
		return
	}
	l := Location{
		ID: uuid.New(), Name: req.Name, Latitude: req.Coordinate.Latitude, Longitude: req.Coordinate.Longitude,
		CoverageKm: cov, HandlingMinutes: hm, Active: req.Active, Functions: fns,
		CapacityUnits: 10, CooledCapacity: 10,
	}
	if err := app.Store.InsertLocation(r.Context(), l); err != nil {
		writeErr(w, 500, "internal_error", "insert")
		return
	}
	_, _ = app.Store.BumpNetworkRevision(r.Context())
	go app.rebuildServiceabilitySnapshot(context.Background())
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "create_location", "location", l.ID.String(), true, map[string]interface{}{"name": l.Name})
	writeData(w, 201, locationPayload(l))
}

func (app *App) handleUpdateLocation(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !requireRole(auth, RoleAdministrator) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		LocationID      string     `json:"locationId"`
		Name            string     `json:"name"`
		Coordinate      Coordinate `json:"coordinate"`
		CoverageKm      *float64   `json:"coverageKm"`
		HandlingMinutes *int       `json:"handlingMinutes"`
		Functions       []string   `json:"functions"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	id, err := uuid.Parse(req.LocationID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	l, err := app.Store.GetLocation(r.Context(), id)
	if err != nil || l == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if !validCoord(req.Coordinate) {
		writeErr(w, 400, "invalid_coordinate", "invalid coordinate")
		return
	}
	l.Name = req.Name
	l.Latitude = req.Coordinate.Latitude
	l.Longitude = req.Coordinate.Longitude
	if req.CoverageKm != nil {
		if *req.CoverageKm <= 0 || *req.CoverageKm > 5 {
			writeErr(w, 400, "invalid_node_coverage", "invalid coverage")
			return
		}
		l.CoverageKm = *req.CoverageKm
	}
	if req.HandlingMinutes != nil {
		if *req.HandlingMinutes < 0 || *req.HandlingMinutes > 1440 {
			writeErr(w, 400, "invalid_handling_time", "invalid handling")
			return
		}
		l.HandlingMinutes = *req.HandlingMinutes
	}
	if req.Functions != nil {
		if len(req.Functions) == 0 {
			writeErr(w, 400, "invalid_location_function", "functions required")
			return
		}
		fns, ok := parseFunctions(req.Functions)
		if !ok {
			writeErr(w, 400, "invalid_location_function", "invalid function")
			return
		}
		l.Functions = fns
	}
	if err := app.Store.UpdateLocation(r.Context(), *l); err != nil {
		writeErr(w, 500, "internal_error", "update")
		return
	}
	_, _ = app.Store.BumpNetworkRevision(r.Context())
	go app.rebuildServiceabilitySnapshot(context.Background())
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "update_location", "location", l.ID.String(), true, nil)
	writeData(w, 201, locationPayload(*l))
