func (app *App) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !requireRole(auth, RoleRequester, RoleAdministrator, RoleDispatcher) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		Origin               Coordinate `json:"origin"`
		OriginType           string     `json:"originType"`
		OriginNodeID         *string    `json:"originNodeId"`
		SampleTypeID         string     `json:"sampleTypeId"`
		RequestedAt          string     `json:"requestedAt"`
		DeliveryDeadline     string     `json:"deliveryDeadline"`
		EarliestCollectionAt *string    `json:"earliestCollectionAt"`
		LatestCollectionAt   *string    `json:"latestCollectionAt"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if !validCoord(req.Origin) {
		writeErr(w, 400, "invalid_origin", "invalid origin")
		return
	}
	if req.OriginType == "" {
		req.OriginType = OriginHome
	}
	if req.OriginType != OriginHome && req.OriginType != OriginClinic && req.OriginType != OriginNode {
		writeErr(w, 400, "invalid_origin_type", "invalid origin type")
		return
	}
	stID, err := uuid.Parse(req.SampleTypeID)
	if err != nil {
		writeErr(w, 404, "not_found", "sample type not found")
		return
	}
	st, _ := app.Store.GetSampleType(r.Context(), stID)
	if st == nil {
		writeErr(w, 404, "not_found", "sample type not found")
		return
	}
	requestedAt, err := parseTime(req.RequestedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid requestedAt")
		return
	}
	deadline, err := parseTime(req.DeliveryDeadline)
	if err != nil {
		writeErr(w, 400, "invalid_deadline", "invalid deadline")
		return
	}
	if !deadline.After(requestedAt) {
		writeErr(w, 400, "invalid_deadline", "deadline must be after requestedAt")
		return
	}
	earliest, latest := requestedAt, deadline
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		t, err := parseTime(*req.EarliestCollectionAt)
		if err != nil {
			writeErr(w, 400, "invalid_time", "invalid earliest")
			return
		}
		earliest = t
	}
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
		t, err := parseTime(*req.LatestCollectionAt)
		if err != nil {
			writeErr(w, 400, "invalid_time", "invalid latest")
			return
		}
		latest = t
	}
	if latest.Before(earliest) {
		writeErr(w, 400, "invalid_collection_window", "invalid collection window")
		return
	}
	var nodeID *uuid.UUID
	if req.OriginNodeID != nil && *req.OriginNodeID != "" {
		id, err := uuid.Parse(*req.OriginNodeID)
		if err != nil {
			writeErr(w, 400, "invalid_origin", "invalid origin node")
			return
		}
		nodeID = &id
	}
	res, err := app.computeServiceability(r.Context(), req.Origin, req.OriginType, nodeID, stID, requestedAt, deadline, earliest, latest, st.RequiresCooledRoute)
	if err != nil {
		writeErr(w, 500, "internal_error", "compute")
		return
	}
	out := map[string]any{
		"serviceable":           res.Serviceable,
		"reason":                res.Reason,
		"serviceabilityVersion": res.ServiceabilityVersion,
	}
	if res.TargetLaboratoryID != nil {
		out["targetLaboratoryId"] = res.TargetLaboratoryID.String()
	}
	if res.EstimatedArrivalAt != nil {
		out["estimatedArrivalAt"] = fmtTime(*res.EstimatedArrivalAt)
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "check_serviceability", "serviceability", "dry-run", true, map[string]interface{}{"reason": res.Reason})
	writeData(w, 200, out)
}

func (app *App) handleReadSnapshot(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	_ = json.NewDecoder(r.Body).Decode(&map[string]any{})
	ver, at, rev, payload, err := app.Store.CurrentSnapshot(r.Context())
	if err != nil {
		writeErr(w, 500, "internal_error", "snapshot")
		return
	}
	var wrap struct {
		Regions                    []map[string]any `json:"regions"`
		ActiveCollectionPointCount int              `json:"activeCollectionPointCount"`
	}
	_ = json.Unmarshal(payload, &wrap)
	if wrap.Regions == nil {
		wrap.Regions = []map[string]any{}
	}
	if wrap.ActiveCollectionPointCount == 0 {
		wrap.ActiveCollectionPointCount = len(wrap.Regions)
	}
	writeData(w, 200, map[string]any{
		"version":                      ver,
		"status":                       "complete",
		"computedAt":                   fmtTime(at),
		"networkRevision":              rev,
		"regions":                      wrap.Regions,
		"activeCollectionPointCount":   wrap.ActiveCollectionPointCount,
	})
}

type createReqBody struct {
	RequesterID              *string    `json:"requesterId"`
	Origin                   Coordinate `json:"origin"`
	OriginType               string     `json:"originType"`
	OriginNodeID             *string    `json:"originNodeId"`
	RequestedAt              string     `json:"requestedAt"`
	DeliveryDeadline         string     `json:"deliveryDeadline"`
	EarliestCollectionAt     *string    `json:"earliestCollectionAt"`
	LatestCollectionAt       *string    `json:"latestCollectionAt"`
	SampleTypeID             string     `json:"sampleTypeId"`
	ContainerType            string     `json:"containerType"`
	TemperatureMinC          float64    `json:"temperatureMinC"`
	TemperatureMaxC          float64    `json:"temperatureMaxC"`
	IncompatibleSampleTypes  []string   `json:"incompatibleSampleTypes"`
	IdempotencyKey           string     `json:"idempotencyKey"`
}

func (app *App) handleCreateRequest(w http.ResponseWriter, r *http.Request) {
	app.createOrIngest(w, r, false)
}

func (app *App) handleIngestPresealed(w http.ResponseWriter, r *http.Request) {
	app.createOrIngest(w, r, true)
}

func (app *App) createOrIngest(w http.ResponseWriter, r *http.Request, presealed bool) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if presealed {
		if !requireRole(auth, RoleCollectionProfessional, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam, RoleAdministrator) {
			writeErr(w, 403, "forbidden", "forbidden")
			return
		}
	} else {
		if !requireRole(auth, RoleRequester, RoleAdministrator, RoleDispatcher) {
			writeErr(w, 403, "forbidden", "forbidden")
			return
		}
	}
	var req createReqBody
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if !validCoord(req.Origin) {
		writeErr(w, 400, "invalid_origin", "invalid origin")
		return
	}
	if req.OriginType == "" {
		if presealed {
			req.OriginType = OriginNode
		} else {
			req.OriginType = OriginHome
		}
	}
	if presealed {
		if req.OriginType != OriginClinic && req.OriginType != OriginNode {
			writeErr(w, 400, "invalid_origin_type", "pre-sealed origin must be clinic or node")
			return
		}
	} else if req.OriginType != OriginHome && req.OriginType != OriginClinic && req.OriginType != OriginNode {
		writeErr(w, 400, "invalid_origin_type", "invalid origin type")
		return
	}
	stID, err := uuid.Parse(req.SampleTypeID)
	if err != nil {
		writeErr(w, 404, "not_found", "sample type")
		return
	}
	st, _ := app.Store.GetSampleType(r.Context(), stID)
	if st == nil {
		writeErr(w, 404, "not_found", "sample type")
		return
	}
	if req.ContainerType == "" || req.TemperatureMinC > req.TemperatureMaxC {
		writeErr(w, 400, "handling_mismatch", "invalid handling")
		return
	}
	// optional match against type
	if req.ContainerType != st.ContainerType {
		// allow if within type range still — mismatch if completely different required
	}
	requestedAt, err := parseTime(req.RequestedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid requestedAt")
		return
	}
	deadline, err := parseTime(req.DeliveryDeadline)
	if err != nil {
		writeErr(w, 400, "invalid_deadline", "invalid deadline")
		return
	}
	if !deadline.After(requestedAt) {
		writeErr(w, 400, "invalid_deadline", "deadline must be after requestedAt")
		return
	}
	earliest, latest := requestedAt, deadline
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		t, err := parseTime(*req.EarliestCollectionAt)
		if err != nil {
			writeErr(w, 400, "invalid_time", "invalid earliest")
			return
		}
		earliest = t
	}
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
		t, err := parseTime(*req.LatestCollectionAt)
		if err != nil {
			writeErr(w, 400, "invalid_time", "invalid latest")
			return
		}
		latest = t
	}
	if latest.Before(earliest) {
		writeErr(w, 400, "invalid_collection_window", "invalid window")
		return
	}
	var nodeID *uuid.UUID
	if req.OriginNodeID != nil && *req.OriginNodeID != "" {
		id, err := uuid.Parse(*req.OriginNodeID)
		if err != nil {
			writeErr(w, 400, "invalid_origin", "invalid origin node")
			return
		}
		loc, _ := app.Store.GetLocation(r.Context(), id)
		if loc == nil {
			writeErr(w, 400, "invalid_origin_state", "unknown origin node")
			return
		}
		nodeID = &id
	}
	requesterID := auth.User.ID
	if req.RequesterID != nil && *req.RequesterID != "" {
		id, err := uuid.Parse(*req.RequesterID)
		if err != nil {
			writeErr(w, 400, "invalid_json", "invalid requester")
			return
		}
		requesterID = id
	}
	var incomp []uuid.UUID
	for _, s := range req.IncompatibleSampleTypes {
		id, err := uuid.Parse(s)
		if err != nil {
			writeErr(w, 400, "handling_mismatch", "invalid incompatible")
			return
		}
		incomp = append(incomp, id)
	}
	if incomp == nil {
		incomp = append([]uuid.UUID{}, st.IncompatibleSampleTypes...)
	}

	res, err := app.computeServiceability(r.Context(), req.Origin, req.OriginType, nodeID, stID, requestedAt, deadline, earliest, latest, st.RequiresCooledRoute)
	if err != nil {
		writeErr(w, 500, "internal_error", "compute")
		return
	}

	sm := Sample{
		ID: uuid.New(), RequestID: uuid.New(), RequesterID: requesterID,
		OriginLat: req.Origin.Latitude, OriginLng: req.Origin.Longitude,
		OriginType: req.OriginType, OriginNodeID: nodeID,
		RequestedAt: requestedAt, DeliveryDeadline: deadline,
		EarliestCollectionAt: earliest, LatestCollectionAt: latest,
		SampleTypeID: stID, ContainerType: req.ContainerType,
		TemperatureMinC: req.TemperatureMinC, TemperatureMaxC: req.TemperatureMaxC,
		IncompatibleSampleTypes: incomp,
		Serviceability: "unserviceable", ServiceabilityReason: res.Reason,
		Status: StatusUnserviceable, AlreadySealed: presealed,
		LatestLat: &req.Origin.Latitude, LatestLng: &req.Origin.Longitude,
	}
	now := time.Now().UTC()
	sm.LocationRecordedAt = &now
	if res.Serviceable {
		sm.Serviceability = "serviceable"
		sm.Status = StatusRequested
		sm.TargetLaboratoryID = res.TargetLaboratoryID
	}
	if err := app.Store.InsertSample(r.Context(), sm); err != nil {
		writeErr(w, 500, "internal_error", "insert sample")
		return
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "create_request", "sample", sm.ID.String(), true, map[string]interface{}{"presealed": presealed})

	var activeIDs []string
	var journeyID *uuid.UUID
	if res.Serviceable && res.Route != nil {
		if presealed {
			sm.CurrentHolderID = &auth.User.ID
			sm.Sealed = true
			sm.SealedAt = &now
			sm.AlreadySealed = true
			sm.Status = StatusSealed
		}
		j, asgs, err := app.materializeJourney(r.Context(), &sm, st, res, presealed, auth.User.ID.String(), auth.ActiveRole)
		if err != nil {
			// keep sample as unserviceable if planning fails due to capacity etc.
			sm.Serviceability = "unserviceable"
			sm.ServiceabilityReason = "insufficient_capacity"
			sm.Status = StatusUnserviceable
			_ = app.Store.UpdateSample(r.Context(), sm)
		} else {
			journeyID = &j.ID
			for _, a := range asgs {
				if a.Status == StatusPending || a.Status == StatusAccepted {
					activeIDs = append(activeIDs, a.ID.String())
				}
			}
			// reload
			if updated, _ := app.Store.GetSample(r.Context(), sm.ID); updated != nil {
				sm = *updated
			}
		}
	}
	if activeIDs == nil {
		activeIDs = []string{}
	}
	out := map[string]any{
		"requestId":              sm.RequestID.String(),
		"sampleId":               sm.ID.String(),
		"serviceability":         sm.Serviceability,
		"serviceabilityReason":   sm.ServiceabilityReason,
		"activeAssignmentIds":    activeIDs,
		"earliestCollectionAt":   fmtTime(sm.EarliestCollectionAt),
		"latestCollectionAt":     fmtTime(sm.LatestCollectionAt),
		"alreadySealed":          sm.AlreadySealed,
		"originType":             sm.OriginType,
	}
	if journeyID != nil {
		out["journeyId"] = journeyID.String()
	}
	if sm.TargetLaboratoryID != nil {
		out["targetLaboratoryId"] = sm.TargetLaboratoryID.String()
	}
	writeData(w, 201, out)
}
"}

