func (app *App) handleAccept(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	aid, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	a, _ := app.Store.GetAssignment(r.Context(), aid)
	if a == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if a.OfferedTo == nil || *a.OfferedTo != auth.User.ID {
		writeErr(w, 409, "assignment_not_offered", "not offered to this worker")
		return
	}
	if a.Status != StatusPending {
		writeErr(w, 409, "assignment_not_offered", "not pending")
		return
	}
	now := time.Now().UTC()
	a.Status = StatusAccepted
	a.WorkerID = &auth.User.ID
	a.AcceptedAt = &now
	if err := app.Store.UpdateAssignment(r.Context(), *a); err != nil {
		writeErr(w, 500, "internal_error", "update")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), a.SampleID)
	if sm != nil {
		if sm.Status == StatusOffered || sm.Status == StatusRequested {
			sm.Status = StatusAccepted
			_ = app.Store.UpdateSample(r.Context(), *sm)
		}
		j, _ := app.Store.GetJourney(r.Context(), a.JourneyID)
		if j != nil && j.Status == StatusPlanned {
			j.Status = StatusActive
			_ = app.Store.UpdateJourney(r.Context(), *j)
		}
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "accept_assignment", "assignment", a.ID.String(), true, nil)
	_, _ = app.Store.AddRealtime(r.Context(), "assignment.accepted", "assignment", a.ID.String(), nil)
	writeData(w, 200, map[string]any{"assignmentId": a.ID.String(), "status": a.Status})
}

