func (app *App) handleCollectSeal(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !requireRole(auth, RoleCollectionProfessional, RoleAdministrator) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		AssignmentID     string     `json:"assignmentId"`
		CollectedAt      string     `json:"collectedAt"`
		Sealed           bool       `json:"sealed"`
		ObservedLocation Coordinate `json:"observedLocation"`
		IdempotencyKey   string     `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if !req.Sealed {
		writeErr(w, 400, "invalid_json", "sealed must be true")
		return
	}
	if !validCoord(req.ObservedLocation) {
		writeErr(w, 400, "invalid_coordinate", "invalid location")
		return
	}
	at, err := parseTime(req.CollectedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid collectedAt")
		return
	}
	aid, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	a, _ := app.Store.GetAssignment(r.Context(), aid)
	if a == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if a.Kind != KindCollection {
		writeErr(w, 409, "invalid_state", "not a collection assignment")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != auth.User.ID {
		writeErr(w, 403, "forbidden", "not your assignment")
		return
	}
	if a.Status != StatusAccepted && a.Status != StatusInProgress {
		writeErr(w, 409, "invalid_state", "assignment not accepted")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), a.SampleID)
	if sm == nil {
		writeErr(w, 404, "not_found", "sample")
		return
	}
	if at.Before(sm.EarliestCollectionAt) || at.After(sm.LatestCollectionAt) {
		writeErr(w, 409, "outside_collection_window", "outside collection window")
		return
	}
	now := time.Now().UTC()
	a.Status = StatusCompleted
	a.CompletedAt = &now
	_ = app.Store.UpdateAssignment(r.Context(), *a)
	sm.Sealed = true
	sm.SealedAt = &at
	sm.Status = StatusSealed
	sm.CurrentHolderID = &auth.User.ID
	sm.LatestLat = &req.ObservedLocation.Latitude
	sm.LatestLng = &req.ObservedLocation.Longitude
	sm.LocationRecordedAt = &at
	_ = app.Store.UpdateSample(r.Context(), *sm)
	st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
	all, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
	_ = app.offerNext(r.Context(), sm, all, st)
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "collect_and_seal", "sample", sm.ID.String(), true, nil)
	_, _ = app.Store.AddRealtime(r.Context(), "sample.sealed", "sample", sm.ID.String(), nil)
	writeData(w, 200, map[string]any{"sampleId": sm.ID.String(), "sealed": true, "status": sm.Status})
}

func (app *App) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	sid, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	fromID, err1 := uuid.Parse(req.FromAssignmentID)
	toID, err2 := uuid.Parse(req.ToAssignmentID)
	if err1 != nil || err2 != nil {
		writeErr(w, 400, "invalid_json", "invalid assignment")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), sid)
	if sm == nil {
		writeErr(w, 404, "not_found", "sample")
		return
	}
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != auth.User.ID {
		writeErr(w, 409, "not_current_holder", "not current holder")
		return
	}
	from, _ := app.Store.GetAssignment(r.Context(), fromID)
	to, _ := app.Store.GetAssignment(r.Context(), toID)
	if from == nil || to == nil || from.SampleID != sid || to.SampleID != sid {
		writeErr(w, 409, "invalid_handoff_pair", "invalid pair")
		return
	}
	if from.WorkerID == nil || *from.WorkerID != auth.User.ID {
		writeErr(w, 409, "invalid_handoff_pair", "sender not on from assignment")
		return
	}
	if to.WorkerID == nil {
		writeErr(w, 409, "invalid_handoff_pair", "receiver not accepted")
		return
	}
	if from.Sequence >= to.Sequence {
		writeErr(w, 409, "invalid_handoff_pair", "not sequential")
		return
	}
	if sm.PendingHandoffID != nil {
		// idempotent-ish: return existing
		h, _ := app.Store.GetHandoff(r.Context(), *sm.PendingHandoffID)
		if h != nil && h.FromAssignmentID == fromID && h.ToAssignmentID == toID {
			writeData(w, 201, handoffPayload(*h))
			return
		}
		writeErr(w, 409, "handoff_already_pending", "already pending")
		return
	}
	now := time.Now().UTC()
	h := Handoff{
		ID: uuid.New(), SampleID: sid, FromAssignmentID: fromID, ToAssignmentID: toID,
		SenderID: auth.User.ID, ReceiverID: *to.WorkerID, Status: "pending",
		SenderConfirmed: false, ReceiverConfirmed: false, InitiatedAt: now,
	}
	if err := app.Store.InsertHandoff(r.Context(), h); err != nil {
		writeErr(w, 500, "internal_error", "insert")
		return
	}
	sm.PendingHandoffID = &h.ID
	_ = app.Store.UpdateSample(r.Context(), *sm)
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "initiate_handoff", "sample", sid.String(), true, map[string]interface{}{"handoffId": h.ID.String()})
	writeData(w, 201, handoffPayload(h))
}

func handoffPayload(h Handoff) map[string]any {
	return map[string]any{
		"handoffId":         h.ID.String(),
		"sampleId":          h.SampleID.String(),
		"fromAssignmentId":  h.FromAssignmentID.String(),
		"toAssignmentId":    h.ToAssignmentID.String(),
		"status":            h.Status,
		"senderConfirmed":   h.SenderConfirmed,
		"receiverConfirmed": h.ReceiverConfirmed,
	}
}

func (app *App) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		HandoffID      string `json:"handoffId"`
		Party          string `json:"party"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Party != "sender" && req.Party != "receiver" {
		writeErr(w, 400, "invalid_json", "invalid party")
		return
	}
	hid, err := uuid.Parse(req.HandoffID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	h, _ := app.Store.GetHandoff(r.Context(), hid)
	if h == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if h.Status == "confirmed" {
		writeData(w, 200, handoffPayload(*h))
		return
	}
	if req.Party == "sender" {
		if h.SenderID != auth.User.ID {
			writeErr(w, 403, "forbidden", "not sender")
			return
		}
		h.SenderConfirmed = true
	} else {
		if h.ReceiverID != auth.User.ID {
			writeErr(w, 403, "forbidden", "not receiver")
			return
		}
		h.ReceiverConfirmed = true
	}
	if h.SenderConfirmed && h.ReceiverConfirmed {
		now := time.Now().UTC()
		h.Status = "confirmed"
		h.ConfirmedAt = &now
		sm, _ := app.Store.GetSample(r.Context(), h.SampleID)
		if sm != nil {
			sm.CurrentHolderID = &h.ReceiverID
			sm.PendingHandoffID = nil
			from, _ := app.Store.GetAssignment(r.Context(), h.FromAssignmentID)
			to, _ := app.Store.GetAssignment(r.Context(), h.ToAssignmentID)
			if from != nil && from.Status != StatusCompleted {
				from.Status = StatusCompleted
				from.CompletedAt = &now
				_ = app.Store.UpdateAssignment(r.Context(), *from)
			}
			if to != nil && to.Status == StatusAccepted {
				to.Status = StatusInProgress
				_ = app.Store.UpdateAssignment(r.Context(), *to)
			}
			if to != nil {
				switch to.Kind {
				case KindTransport:
					sm.Status = StatusInTransit
				case KindNode:
					sm.Status = StatusAtNode
				case KindLaboratory:
					sm.Status = StatusAtLaboratory
				}
			}
			_ = app.Store.UpdateSample(r.Context(), *sm)
			st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
			all, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
			_ = app.offerNext(r.Context(), sm, all, st)
		}
	}
	_ = app.Store.UpdateHandoff(r.Context(), *h)
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "confirm_handoff", "handoff", h.ID.String(), true, map[string]interface{}{"party": req.Party, "status": h.Status})
	writeData(w, 200, handoffPayload(*h))
}

func (app *App) handleConfirmReceipt(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !requireRole(auth, RoleLaboratoryTeam, RoleAdministrator) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		ReceivedAt     string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	sid, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	lid, err := uuid.Parse(req.LaboratoryID)
	if err != nil {
		writeErr(w, 400, "invalid_json", "invalid laboratory")
		return
	}
	at, err := parseTime(req.ReceivedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid receivedAt")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), sid)
	if sm == nil {
		writeErr(w, 404, "not_found", "sample")
		return
	}
	if sm.Status == StatusReceived {
		writeData(w, 200, map[string]any{"sampleId": sm.ID.String(), "status": sm.Status})
		return
	}
	if at.After(sm.DeliveryDeadline) {
		// still receive but mark expired? Spec: if received after deadline it's still received; expired is if no valid route
	}
	sm.Status = StatusReceived
	sm.ReceivedLaboratoryID = &lid
	sm.ReceivedAt = &at
	sm.CurrentHolderID = &auth.User.ID
	sm.LocationRecordedAt = &at
	_ = app.Store.UpdateSample(r.Context(), *sm)
	_ = app.Store.ReleaseReservationsForSample(r.Context(), sm.ID)
	if sm.ActiveJourneyID != nil {
		j, _ := app.Store.GetJourney(r.Context(), *sm.ActiveJourneyID)
		if j != nil {
			j.Status = StatusCompleted
			_ = app.Store.UpdateJourney(r.Context(), *j)
		}
	}
	asgs, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
	now := time.Now().UTC()
	for _, a := range asgs {
		if a.Kind == KindLaboratory && (a.Status == StatusAccepted || a.Status == StatusInProgress || a.Status == StatusPending) {
			a.Status = StatusCompleted
			a.CompletedAt = &now
			if a.WorkerID == nil {
				a.WorkerID = &auth.User.ID
			}
			_ = app.Store.UpdateAssignment(r.Context(), a)
		}
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "confirm_laboratory_receipt", "sample", sm.ID.String(), true, nil)
	_, _ = app.Store.AddRealtime(r.Context(), "sample.received", "sample", sm.ID.String(), nil)
	writeData(w, 200, map[string]any{"sampleId": sm.ID.String(), "status": sm.Status})
}

