func (app *App) handleCheckpoint(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		SampleID               string  `json:"sampleId"`
		AssignmentID           string  `json:"assignmentId"`
		LocationID             *string `json:"locationId"`
		ContainerType          string  `json:"containerType"`
		ObservedTemperatureC   float64 `json:"observedTemperatureC"`
		RecordedAt             string  `json:"recordedAt"`
		IdempotencyKey         string  `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.ContainerType == "" {
		writeErr(w, 400, "invalid_json", "container required")
		return
	}
	sid, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	aid, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	at, err := parseTime(req.RecordedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid recordedAt")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), sid)
	if sm == nil {
		writeErr(w, 404, "not_found", "sample")
		return
	}
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != auth.User.ID {
		writeErr(w, 409, "not_current_holder", "not current holder")
		return
	}
	var locID *uuid.UUID
	if req.LocationID != nil && *req.LocationID != "" {
		id, err := uuid.Parse(*req.LocationID)
		if err != nil {
			writeErr(w, 400, "invalid_json", "invalid location")
			return
		}
		locID = &id
	}
	compliant := req.ContainerType == sm.ContainerType &&
		req.ObservedTemperatureC >= sm.TemperatureMinC &&
		req.ObservedTemperatureC <= sm.TemperatureMaxC
	cid := uuid.New()
	if err := app.Store.InsertCheckpoint(r.Context(), cid, sid, aid, locID, req.ContainerType, req.ObservedTemperatureC, at, compliant); err != nil {
		writeErr(w, 500, "internal_error", "insert")
		return
	}
	if !compliant {
		sm.Status = StatusException
		sm.Exception = map[string]interface{}{
			"reason":                 "handling_checkpoint_violation",
			"containerType":          req.ContainerType,
			"observedTemperatureC":   req.ObservedTemperatureC,
		}
		_ = app.Store.UpdateSample(r.Context(), *sm)
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "handling_checkpoint", "sample", sid.String(), true, map[string]interface{}{"compliant": compliant})
	out := map[string]any{"checkpointId": cid.String(), "compliant": compliant}
	if !compliant {
		out["exception"] = sm.Exception
	}
	writeData(w, 201, out)
}

func (app *App) handleRecordLocation(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		AssignmentID string     `json:"assignmentId"`
		Coordinate   Coordinate `json:"coordinate"`
		RecordedAt   string     `json:"recordedAt"`
		Sequence     int        `json:"sequence"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if !validCoord(req.Coordinate) {
		writeErr(w, 400, "invalid_coordinate", "invalid coordinate")
		return
	}
	if req.Sequence < 1 {
		writeErr(w, 400, "invalid_json", "sequence must be >= 1")
		return
	}
	at, err := parseTime(req.RecordedAt)
	if err != nil {
		writeErr(w, 400, "invalid_time", "invalid recordedAt")
		return
	}
	aid, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	a, _ := app.Store.GetAssignment(r.Context(), aid)
	if a == nil {
		writeErr(w, 404, "not_found", "assignment")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != auth.User.ID {
		writeErr(w, 403, "forbidden", "not your assignment")
		return
	}
	last, err := app.Store.LastWorkerLocSeq(r.Context(), aid)
	if err != nil {
		writeErr(w, 500, "internal_error", "seq")
		return
	}
	if req.Sequence <= last {
		writeErr(w, 409, "stale_location", "sequence not increasing")
		return
	}
	if err := app.Store.InsertWorkerLocation(r.Context(), auth.User.ID, aid, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, at); err != nil {
		writeErr(w, 500, "internal_error", "insert")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), a.SampleID)
	if sm != nil && sm.CurrentHolderID != nil && *sm.CurrentHolderID == auth.User.ID {
		sm.LatestLat = &req.Coordinate.Latitude
		sm.LatestLng = &req.Coordinate.Longitude
		sm.LocationRecordedAt = &at
		_ = app.Store.UpdateSample(r.Context(), *sm)
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "record_location", "assignment", aid.String(), true, nil)
	writeData(w, 200, map[string]any{"assignmentId": aid.String(), "sequence": req.Sequence})
}

func (app *App) handleProgress(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		Note           string `json:"note"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Status != StatusInProgress && req.Status != StatusCompleted {
		writeErr(w, 400, "invalid_json", "invalid status")
		return
	}
	aid, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	a, _ := app.Store.GetAssignment(r.Context(), aid)
	if a == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != auth.User.ID {
		writeErr(w, 403, "forbidden", "not your assignment")
		return
	}
	now := time.Now().UTC()
	a.Status = req.Status
	if req.Status == StatusCompleted {
		a.CompletedAt = &now
	}
	_ = app.Store.UpdateAssignment(r.Context(), *a)
	sm, _ := app.Store.GetSample(r.Context(), a.SampleID)
	if sm != nil && req.Status == StatusInProgress {
		if a.Kind == KindTransport {
			sm.Status = StatusInTransit
		} else if a.Kind == KindCollection {
			sm.Status = StatusCollecting
		}
		_ = app.Store.UpdateSample(r.Context(), *sm)
	}
	if sm != nil && req.Status == StatusCompleted {
		st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
		all, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
		_ = app.offerNext(r.Context(), sm, all, st)
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "update_progress", "assignment", a.ID.String(), true, map[string]interface{}{"status": req.Status, "note": req.Note})
	writeData(w, 200, map[string]any{"assignmentId": a.ID.String(), "status": a.Status})
}

func (app *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		Role string `json:"role"`
	}
	_ = json.NewDecoder(r.Body).Decode(&req)
	role := auth.ActiveRole
	if req.Role != "" {
		if req.Role != auth.ActiveRole {
			writeErr(w, 403, "forbidden", "role must match active role")
			return
		}
		role = req.Role
	}
	now := time.Now().UTC()
	var pending, inProg, completed []map[string]any

	switch role {
	case RoleRequester:
		samples, _ := app.Store.ListSamplesByRequester(r.Context(), auth.User.ID)
		for _, sm := range samples {
			item := app.sampleWorkItem(r.Context(), sm, now)
			switch {
			case sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired:
				completed = append(completed, item)
			case sm.Status == StatusRequested || sm.Status == StatusOffered || sm.Status == StatusUnserviceable:
				pending = append(pending, item)
			default:
				inProg = append(inProg, item)
			}
		}
	case RoleAdministrator, RoleDispatcher:
		samples, _ := app.Store.ListSamples(r.Context())
		for _, sm := range samples {
			item := app.sampleWorkItem(r.Context(), sm, now)
			switch {
			case sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired:
				completed = append(completed, item)
			case sm.Status == StatusRequested || sm.Status == StatusOffered || sm.Status == StatusUnserviceable:
				pending = append(pending, item)
			default:
				inProg = append(inProg, item)
			}
		}
	default:
		asgs, _ := app.Store.ListAssignmentsForWorker(r.Context(), auth.User.ID)
		for _, a := range asgs {
			// filter by role kind
			if !assignmentMatchesRole(a.Kind, role) {
				continue
			}
			item := app.assignmentWorkItem(r.Context(), a)
			switch a.Status {
			case StatusCompleted, StatusCancelled:
				completed = append(completed, item)
			case StatusAccepted, StatusInProgress:
				inProg = append(inProg, item)
			default:
				pending = append(pending, item)
			}
		}
	}
	if pending == nil {
		pending = []map[string]any{}
	}
	if inProg == nil {
		inProg = []map[string]any{}
	}
	if completed == nil {
		completed = []map[string]any{}
	}
	writeData(w, 200, map[string]any{
		"role":              role,
		"pending":           pending,
		"inProgress":        inProg,
		"completed":         completed,
		"current":           append(append([]map[string]any{}, pending...), inProg...),
		"past":              completed,
	})
}

func assignmentMatchesRole(kind, role string) bool {
	switch role {
	case RoleCollectionProfessional:
		return kind == KindCollection
	case RoleDeliveryPartner:
		return kind == KindTransport
	case RoleNodeHandler:
		return kind == KindNode
	case RoleLaboratoryTeam:
		return kind == KindLaboratory
	}
	return true
}

