func (app *App) canSeeSample(auth *AuthContext, sm *Sample) bool {
	if auth == nil || sm == nil {
		return false
	}
	if requireRole(auth, RoleAdministrator, RoleDispatcher) {
		return true
	}
	if requireRole(auth, RoleRequester) && sm.RequesterID == auth.User.ID {
		return true
	}
	if sm.CurrentHolderID != nil && *sm.CurrentHolderID == auth.User.ID {
		return true
	}
	asgs, _ := app.Store.ListAssignmentsForSample(context.Background(), sm.ID)
	for _, a := range asgs {
		if a.WorkerID != nil && *a.WorkerID == auth.User.ID {
			return true
		}
		if a.OfferedTo != nil && *a.OfferedTo == auth.User.ID {
			return true
		}
	}
	return false
}

func (app *App) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
