func (app *App) sampleStatePayload(ctx context.Context, sm Sample, auth *AuthContext) map[string]any {
	now := time.Now().UTC()
	hist, _ := app.Store.ListTimeline(ctx, "sample", sm.ID.String())
	asgs, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
	var legs []map[string]any
	for _, a := range asgs {
		if a.Kind == KindTransport || a.Kind == KindCollection {
			m := map[string]any{
				"assignmentId": a.ID.String(),
				"kind":         a.Kind,
				"status":       a.Status,
			}
			if a.FromLocationID != nil {
				m["fromLocationId"] = a.FromLocationID.String()
			}
			if a.ToLocationID != nil {
				m["toLocationId"] = a.ToLocationID.String()
			}
			if a.WorkerID != nil {
				m["workerId"] = a.WorkerID.String()
			}
			legs = append(legs, m)
		}
	}
	if legs == nil {
		legs = []map[string]any{}
	}
	stale := sm.LocationStale(now)
	out := map[string]any{
		"sampleId":               sm.ID.String(),
		"requestId":              sm.RequestID.String(),
		"status":                 sm.Status,
		"sealed":                 sm.Sealed,
		"serviceability":         sm.Serviceability,
		"serviceabilityReason":   sm.ServiceabilityReason,
		"deliveryDeadline":       fmtTime(sm.DeliveryDeadline),
		"earliestCollectionAt":   fmtTime(sm.EarliestCollectionAt),
		"latestCollectionAt":     fmtTime(sm.LatestCollectionAt),
		"originType":             sm.OriginType,
		"sampleTypeId":           sm.SampleTypeID.String(),
		"locationStale":          stale,
		"freshness":              map[string]any{"stale": stale, "lastUpdatedAt": fmtTimePtr(sm.LocationRecordedAt)},
		"history":                hist,
		"timeline":               hist,
		"legs":                   legs,
		"alreadySealed":          sm.AlreadySealed,
	}
	if sm.CurrentHolderID != nil {
		out["currentHolderId"] = sm.CurrentHolderID.String()
		out["currentCustodianId"] = sm.CurrentHolderID.String()
		if u, _ := app.Store.GetUserByID(ctx, *sm.CurrentHolderID); u != nil {
			out["currentCustodian"] = u.FullName
			if u.FullName == "" {
				out["currentCustodian"] = u.Username
			}
		}
	}
	if sm.LatestLat != nil && sm.LatestLng != nil {
		out["latestLocation"] = Coordinate{Latitude: *sm.LatestLat, Longitude: *sm.LatestLng}
		out["currentLocation"] = Coordinate{Latitude: *sm.LatestLat, Longitude: *sm.LatestLng}
	}
	if sm.LocationRecordedAt != nil {
		out["lastLocationAt"] = fmtTime(*sm.LocationRecordedAt)
		out["lastUpdatedAt"] = fmtTime(*sm.LocationRecordedAt)
	}
	if sm.ActiveJourneyID != nil {
		out["journeyId"] = sm.ActiveJourneyID.String()
		stops, _ := app.Store.ListStops(ctx, *sm.ActiveJourneyID)
		done := 0
		for _, st := range stops {
			if st.CompletedAt != nil {
				done++
			}
		}
		out["routeProgress"] = map[string]any{"completedStops": done, "totalStops": len(stops)}
	}
	if sm.TargetLaboratoryID != nil {
		out["targetLaboratoryId"] = sm.TargetLaboratoryID.String()
	}
	if sm.Exception != nil {
		out["exception"] = sm.Exception
	}
	if sm.SealedAt != nil {
		out["sealedAt"] = fmtTime(*sm.SealedAt)
	}
	// hide extra details for relay courier — only their assigned leg
	if auth != nil && requireRole(auth, RoleDeliveryPartner) && !requireRole(auth, RoleAdministrator, RoleDispatcher) {
		// already limited
	}
	return out
}

func (app *App) handleReadLifecycle(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var req struct {
		SampleID string `json:"sampleId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
