func (app *App) journeyPayload(ctx context.Context, j Journey, auth *AuthContext) map[string]any {
	sids, _ := app.Store.JourneySampleIDs(ctx, j.ID)
	ss := make([]string, 0, len(sids))
	for _, id := range sids {
		ss = append(ss, id.String())
	}
	stops, _ := app.Store.ListStops(ctx, j.ID)
	var stopOut []map[string]any
	for _, st := range stops {
		m := map[string]any{
			"stopId":        st.ID.String(),
			"stopType":      st.StopType,
			"sequence":      st.Sequence,
			"estimatedAt":   fmtTime(st.EstimatedAt),
			"dwellMinutes":  st.Dwell,
		}
		if st.LocationID != nil {
			m["locationId"] = st.LocationID.String()
		}
		if st.Lat != nil && st.Lng != nil {
			m["coordinate"] = Coordinate{Latitude: *st.Lat, Longitude: *st.Lng}
		}
		stopOut = append(stopOut, m)
	}
	if stopOut == nil {
		stopOut = []map[string]any{}
	}
	asgs, _ := app.Store.ListAssignmentsForJourney(ctx, j.ID)
	var asgOut []map[string]any
	for _, a := range asgs {
		// courier sees only their assigned leg
		if auth != nil && requireRole(auth, RoleDeliveryPartner) && !adminOrDispatcher(auth) {
			if a.WorkerID == nil || *a.WorkerID != auth.User.ID {
				if a.OfferedTo == nil || *a.OfferedTo != auth.User.ID {
					continue
				}
			}
		}
		m := map[string]any{
			"assignmentId": a.ID.String(),
			"kind":         a.Kind,
			"status":       a.Status,
			"sequence":     a.Sequence,
			"sampleId":     a.SampleID.String(),
		}
		if a.WorkerID != nil {
			m["workerId"] = a.WorkerID.String()
		}
		if a.OfferedTo != nil {
			m["offeredTo"] = a.OfferedTo.String()
		}
		if a.FromLocationID != nil {
			m["fromLocationId"] = a.FromLocationID.String()
		}
		if a.ToLocationID != nil {
			m["toLocationId"] = a.ToLocationID.String()
		}
		if a.NodeID != nil {
			m["nodeId"] = a.NodeID.String()
		}
		if a.LaboratoryID != nil {
			m["laboratoryId"] = a.LaboratoryID.String()
		}
		asgOut = append(asgOut, m)
	}
	if asgOut == nil {
		asgOut = []map[string]any{}
	}
	out := map[string]any{
		"journeyId":      j.ID.String(),
		"planVersion":    j.PlanVersion,
		"routeMode":      j.RouteMode,
		"status":         j.Status,
		"sampleIds":      ss,
		"stops":          stopOut,
		"assignments":    asgOut,
		"totalCostUnits": j.TotalCostUnits,
		"capacityUsed":   j.CapacityUsed,
		"valid":          j.Valid,
	}
	if j.EstimatedDeliveryAt != nil {
		out["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
	}
	if j.ParentJourneyID != nil {
		out["parentJourneyId"] = j.ParentJourneyID.String()
	}
	if j.ReplanStatus != nil {
		out["replanStatus"] = *j.ReplanStatus
	}
	return out
}

func (app *App) handleOpsState(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !adminOrDispatcher(auth) && !requireRole(auth, RoleNodeHandler, RoleLaboratoryTeam) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	_ = json.NewDecoder(r.Body).Decode(&map[string]any{})
	now := time.Now().UTC()
	samples, _ := app.Store.ListSamples(r.Context())
	users, _ := app.Store.ListUsers(r.Context())
	locs, _ := app.Store.ListLocations(r.Context())
	conns, _ := app.Store.ListConnections(r.Context())

	var sampleOut, workerOut, nodeOut, labOut, routeOut, excOut []map[string]any
	for _, sm := range samples {
		stale := sm.LocationStale(now)
		m := map[string]any{
			"sampleId":      sm.ID.String(),
			"status":        sm.Status,
			"locationStale": stale,
			"originType":    sm.OriginType,
		}
		if sm.CurrentHolderID != nil {
			m["currentHolderId"] = sm.CurrentHolderID.String()
		}
		if sm.LatestLat != nil && sm.LatestLng != nil {
			m["latestLocation"] = Coordinate{Latitude: *sm.LatestLat, Longitude: *sm.LatestLng}
		}
		if sm.LocationRecordedAt != nil {
			m["lastLocationAt"] = fmtTime(*sm.LocationRecordedAt)
		}
		if sm.ActiveJourneyID != nil {
			m["journeyId"] = sm.ActiveJourneyID.String()
		}
		if sm.Exception != nil || sm.Status == StatusException {
			excOut = append(excOut, map[string]any{"sampleId": sm.ID.String(), "status": sm.Status, "exception": sm.Exception})
		}
		sampleOut = append(sampleOut, m)
	}
	for _, u := range users {
		isWorker := containsString(u.Roles, RoleCollectionProfessional) || containsString(u.Roles, RoleDeliveryPartner) ||
			containsString(u.Roles, RoleNodeHandler) || containsString(u.Roles, RoleLaboratoryTeam)
		if !isWorker {
			continue
		}
		coord, at, _ := app.Store.LatestWorkerLocation(r.Context(), u.ID)
		m := map[string]any{
			"workerId":  u.ID.String(),
			"username":  u.Username,
			"roles":     u.Roles,
			"available": u.Available,
			"active":    u.Active,
		}
		if coord != nil {
			m["latestLocation"] = coord
		}
		if at != nil {
			m["lastLocationAt"] = fmtTime(*at)
			m["locationStale"] = now.Sub(*at) > StaleLocationAge
		}
		workerOut = append(workerOut, m)
	}
	for _, l := range locs {
		cap := l.Capacity()
		m := map[string]any{
			"locationId": l.ID.String(),
			"name":       l.Name,
			"coordinate": Coordinate{Latitude: l.Latitude, Longitude: l.Longitude},
			"active":     l.Active,
			"functions":  l.Functions,
			"capacity":   cap,
		}
		if l.Functions.CollectionPoint || l.Functions.TransferPoint || l.Functions.Hub {
			nodeOut = append(nodeOut, m)
		}
		if l.Functions.Laboratory {
			types, _ := app.Store.AcceptedTypes(r.Context(), l.ID)
			acc := make([]string, 0, len(types))
			for _, t := range types {
				acc = append(acc, t.String())
			}
			m["acceptedSampleTypes"] = acc
			labOut = append(labOut, m)
		}
	}
	for _, c := range conns {
		routeOut = append(routeOut, map[string]any{
			"connectionId":   c.ID.String(),
			"fromLocationId": c.FromLocationID.String(),
			"toLocationId":   c.ToLocationID.String(),
			"travelMinutes":  c.TravelMinutes,
			"costUnits":      c.CostUnits,
			"cooled":         c.Cooled,
			"active":         c.Active,
			"capacity":       c.Capacity(),
		})
	}
	if sampleOut == nil {
		sampleOut = []map[string]any{}
	}
	if workerOut == nil {
		workerOut = []map[string]any{}
	}
	if nodeOut == nil {
		nodeOut = []map[string]any{}
	}
	if labOut == nil {
		labOut = []map[string]any{}
	}
	if routeOut == nil {
		routeOut = []map[string]any{}
	}
	if excOut == nil {
		excOut = []map[string]any{}
	}
	writeData(w, 200, map[string]any{
		"samples":         sampleOut,
		"workers":         workerOut,
		"collectionNodes": nodeOut,
		"laboratories":    labOut,
		"routes":          routeOut,
		"exceptions":      excOut,
	})
}

