func (app *App) handleEvents(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	var since int64
	if s := r.URL.Query().Get("since"); s != "" {
		_, _ = json.Unmarshal([]byte(s), &since)
		var n int64
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				n = n*10 + int64(ch-'0')
			}
		}
		since = n
	}
	evs, cursor, err := app.Store.ListRealtime(r.Context(), since)
	if err != nil {
		writeErr(w, 500, "internal_error", "events")
		return
	}
	writeData(w, 200, map[string]any{"events": evs, "cursor": cursor})
}

func (app *App) handleSearchAudit(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !adminOrDispatcher(auth) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		Query      string  `json:"query"`
		ActorID    string  `json:"actorId"`
		EntityType string  `json:"entityType"`
		EntityID   string  `json:"entityId"`
		Action     string  `json:"action"`
		Role       string  `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   *string `json:"fromTime"`
		ToTime     *string `json:"toTime"`
		Limit      int     `json:"limit"`
		Offset     int     `json:"offset"`
		Order      string  `json:"order"`
	}
	if err := decodeJSON(r, &req); err != nil && err.Error() != "EOF" {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.Limit <= 0 {
		req.Limit = 50
	}
	if req.Limit > 200 {
		req.Limit = 200
	}
	q := AuditQuery{
		Query: req.Query, ActorID: req.ActorID, EntityType: req.EntityType, EntityID: req.EntityID,
		Action: req.Action, Role: req.Role, Success: req.Success, Limit: req.Limit, Offset: req.Offset, Order: req.Order,
	}
	if req.FromTime != nil && *req.FromTime != "" {
		t, err := parseTime(*req.FromTime)
		if err != nil {
			writeErr(w, 400, "invalid_time", "invalid fromTime")
			return
		}
		q.FromTime = &t
	}
	if req.ToTime != nil && *req.ToTime != "" {
		t, err := parseTime(*req.ToTime)
		if err != nil {
			writeErr(w, 400, "invalid_time", "invalid toTime")
			return
		}
		q.ToTime = &t
	}
	entries, total, err := app.searchAudit(r.Context(), q)
	if err != nil {
		writeErr(w, 500, "internal_error", "search")
		return
	}
	writeData(w, 200, map[string]any{"entries": entries, "total": total})
}

func (app *App) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !adminOrDispatcher(auth) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	jid, err := uuid.Parse(req.JourneyID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	j, _ := app.Store.GetJourney(r.Context(), jid)
	if j == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if req.ExpectedPlanVersion != j.PlanVersion {
		writeErr(w, 409, "stale_plan", "stale plan version")
		return
	}
	if j.Status == StatusCompleted {
		writeErr(w, 409, "invalid_state", "already completed")
		return
	}
	j.PlanVersion++
	j.Status = StatusCancelled
	_ = app.Store.UpdateJourney(r.Context(), *j)
	asgs, _ := app.Store.ListAssignmentsForJourney(r.Context(), j.ID)
	for _, a := range asgs {
		if a.Status != StatusCompleted {
			a.Status = StatusCancelled
			a.OfferedTo = nil
			_ = app.Store.UpdateAssignment(r.Context(), a)
		}
	}
	sids, _ := app.Store.JourneySampleIDs(r.Context(), j.ID)
	for _, sid := range sids {
		sm, _ := app.Store.GetSample(r.Context(), sid)
		if sm != nil && sm.Status != StatusReceived {
			sm.Status = StatusCancelled
			_ = app.Store.UpdateSample(r.Context(), *sm)
			_ = app.Store.ReleaseReservationsForSample(r.Context(), sid)
		}
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "cancel_journey", "journey", j.ID.String(), true, map[string]interface{}{"reason": req.Reason})
	writeData(w, 200, map[string]any{"journeyId": j.ID.String(), "status": j.Status, "planVersion": j.PlanVersion})
}

func (app *App) replanJourney(w http.ResponseWriter, r *http.Request, jid uuid.UUID, expected int, reason string) {
	auth := getAuth(r)
	j, _ := app.Store.GetJourney(r.Context(), jid)
	if j == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if expected != j.PlanVersion {
		writeErr(w, 409, "stale_plan", "stale plan version")
		return
	}
	if j.Status == StatusCompleted || j.Status == StatusCancelled {
		writeErr(w, 409, "invalid_state", "cannot replan completed")
		return
	}
	sids, _ := app.Store.JourneySampleIDs(r.Context(), j.ID)
	if len(sids) == 0 {
		writeErr(w, 409, "invalid_state", "no samples")
		return
	}
	sm, _ := app.Store.GetSample(r.Context(), sids[0])
	if sm == nil {
		writeErr(w, 404, "not_found", "sample")
		return
	}
	// preserve holder and completed work
	holder := sm.CurrentHolderID
	st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
	origin := Coordinate{Latitude: sm.OriginLat, Longitude: sm.OriginLng}
	if sm.LatestLat != nil {
		origin.Latitude = *sm.LatestLat
		origin.Longitude = *sm.LatestLng
	}
	originType := sm.OriginType
	if sm.Sealed {
		originType = OriginNode
	}
	res, err := app.computeServiceability(r.Context(), origin, originType, sm.OriginNodeID, sm.SampleTypeID, time.Now().UTC(), sm.DeliveryDeadline, sm.EarliestCollectionAt, sm.LatestCollectionAt, st != nil && st.RequiresCooledRoute)
	if err != nil {
		writeErr(w, 500, "internal_error", "compute")
		return
	}
	j.PlanVersion++
	if !res.Serviceable {
		j.Valid = false
		rs := "expired"
		j.ReplanStatus = &rs
		sm.Status = StatusExpired
		sm.Serviceability = "unserviceable"
		sm.ServiceabilityReason = res.Reason
		sm.CurrentHolderID = holder
		_ = app.Store.UpdateSample(r.Context(), *sm)
		_ = app.Store.UpdateJourney(r.Context(), *j)
		app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "replan", "journey", j.ID.String(), true, map[string]interface{}{"result": "expired", "reason": reason})
		writeData(w, 200, map[string]any{"journeyId": j.ID.String(), "planVersion": j.PlanVersion, "status": "expired", "replanStatus": "expired"})
		return
	}
	// cancel unfinished assignments, keep completed
	asgs, _ := app.Store.ListAssignmentsForJourney(r.Context(), j.ID)
	maxSeq := 0
	for _, a := range asgs {
		if a.Status == StatusCompleted && a.Sequence > maxSeq {
			maxSeq = a.Sequence
		}
		if a.Status != StatusCompleted {
			a.Status = StatusCancelled
			a.OfferedTo = nil
			_ = app.Store.UpdateAssignment(r.Context(), a)
		}
	}
	_ = app.Store.DeleteUncompletedStops(r.Context(), j.ID)
	_ = app.Store.ReleaseReservationsForSample(r.Context(), sm.ID)

	// recreate unfinished legs from remaining route
	route := res.Route
	cooled := route.NeedsCooled
	for _, n := range route.Nodes {
		loc, _ := app.Store.GetLocation(r.Context(), n)
		if loc == nil {
			continue
		}
		need := false
		if cooled {
			need = loc.CooledCapacity > 0
		} else {
			need = loc.CapacityUnits > 0
		}
		if need {
			_ = app.Store.ReserveCapacity(r.Context(), "location", n, sm.ID, j.ID, cooled, 1)
		}
	}
	seq := maxSeq + 1
	var newAsgs []Assignment
	for _, h := range route.Hops {
		from, to := h.From, h.To
		a := Assignment{
			ID: uuid.New(), JourneyID: j.ID, SampleID: sm.ID, Kind: KindTransport,
			Sequence: seq, Status: StatusPending, FromLocationID: &from, ToLocationID: &to,
		}
		_ = app.Store.InsertAssignment(r.Context(), a)
		newAsgs = append(newAsgs, a)
		seq++
	}
	labID := route.Laboratory
	la := Assignment{
		ID: uuid.New(), JourneyID: j.ID, SampleID: sm.ID, Kind: KindLaboratory,
		Sequence: seq, Status: StatusPending, LaboratoryID: &labID, ToLocationID: &labID,
	}
	_ = app.Store.InsertAssignment(r.Context(), la)
	newAsgs = append(newAsgs, la)

	sm.TargetLaboratoryID = &route.Laboratory
	sm.CurrentHolderID = holder
	sm.ActiveJourneyID = &j.ID
	_ = app.Store.UpdateSample(r.Context(), *sm)
	all, _ := app.Store.ListAssignmentsForSample(r.Context(), sm.ID)
	_ = app.offerNext(r.Context(), sm, all, st)
	j.Valid = true
	rs := "replanned"
	j.ReplanStatus = &rs
	j.EstimatedDeliveryAt = res.EstimatedArrivalAt
	j.TotalCostUnits = route.TotalCost
	_ = app.Store.UpdateJourney(r.Context(), *j)
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "replan", "journey", j.ID.String(), true, map[string]interface{}{"reason": reason})
	writeData(w, 200, map[string]any{"journeyId": j.ID.String(), "planVersion": j.PlanVersion, "status": j.Status, "replanStatus": "replanned"})
}

