		return
	}
	jid, err := uuid.Parse(req.JourneyID)
	if err != nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	j, _ := app.Store.GetJourney(r.Context(), jid)
	if j == nil {
		writeErr(w, 404, "not_found", "not found")
		return
	}
	if req.ExpectedPlanVersion != j.PlanVersion {
		writeErr(w, 409, "stale_plan", "stale plan")
		return
	}
	j.PlanVersion++
	_ = app.Store.UpdateJourney(r.Context(), *j)
	// create a child journey for split samples (simple clone of remaining)
	child := Journey{
		ID: uuid.New(), ParentJourneyID: &j.ID, PlanVersion: 1, RouteMode: j.RouteMode,
		Status: StatusPlanned, EstimatedDeliveryAt: j.EstimatedDeliveryAt,
		TotalCostUnits: j.TotalCostUnits, CapacityUsed: 1, Valid: true,
	}
	_ = app.Store.InsertJourney(r.Context(), child)
	for _, s := range req.SampleIDs {
		sid, err := uuid.Parse(s)
		if err != nil {
			continue
		}
		_ = app.Store.AddJourneySample(r.Context(), child.ID, sid)
		sm, _ := app.Store.GetSample(r.Context(), sid)
		if sm != nil {
			sm.ActiveJourneyID = &child.ID
			_ = app.Store.UpdateSample(r.Context(), *sm)
		}
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "split_journey", "journey", j.ID.String(), true, map[string]interface{}{"child": child.ID.String()})
	writeData(w, 200, map[string]any{
		"originalJourneyId": j.ID.String(),
		"newJourneyId":      child.ID.String(),
		"planVersion":       j.PlanVersion,
	})
}

func (app *App) handleMerge(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !adminOrDispatcher(auth) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		JourneyIDs          []string `json:"journeyIds"`
		ExpectedPlanVersions []int   `json:"expectedPlanVersions"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if len(req.JourneyIDs) < 2 {
		writeErr(w, 400, "invalid_json", "need at least two journeys")
		return
	}
	var journeys []Journey
	var samples []Sample
	for i, js := range req.JourneyIDs {
		id, err := uuid.Parse(js)
		if err != nil {
			writeErr(w, 404, "not_found", "not found")
			return
		}
		j, _ := app.Store.GetJourney(r.Context(), id)
		if j == nil {
			writeErr(w, 404, "not_found", "not found")
			return
		}
		if i < len(req.ExpectedPlanVersions) && req.ExpectedPlanVersions[i] != j.PlanVersion {
			writeErr(w, 409, "stale_plan", "stale plan")
			return
		}
		journeys = append(journeys, *j)
		sids, _ := app.Store.JourneySampleIDs(r.Context(), j.ID)
		for _, sid := range sids {
			sm, _ := app.Store.GetSample(r.Context(), sid)
			if sm != nil {
				samples = append(samples, *sm)
			}
		}
	}
	// compatibility
	if !compatibleBatch(samples) {
		writeErr(w, 409, "incompatible_batch", "samples cannot travel together")
		return
	}
	primary := journeys[0]
	primary.PlanVersion++
	primary.RouteMode = RouteBatched
	_ = app.Store.UpdateJourney(r.Context(), primary)
	for i := 1; i < len(journeys); i++ {
		sids, _ := app.Store.JourneySampleIDs(r.Context(), journeys[i].ID)
		for _, sid := range sids {
			_ = app.Store.AddJourneySample(r.Context(), primary.ID, sid)
			sm, _ := app.Store.GetSample(r.Context(), sid)
			if sm != nil {
				sm.ActiveJourneyID = &primary.ID
				_ = app.Store.UpdateSample(r.Context(), *sm)
			}
		}
		journeys[i].Status = StatusCancelled
		journeys[i].PlanVersion++
		_ = app.Store.UpdateJourney(r.Context(), journeys[i])
	}
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "merge_journeys", "journey", primary.ID.String(), true, nil)
	writeData(w, 200, map[string]any{"journeyId": primary.ID.String(), "planVersion": primary.PlanVersion, "routeMode": primary.RouteMode})
}

func compatibleBatch(samples []Sample) bool {
	for i, a := range samples {
		stA, _ := (*App)(nil).unused()
		_ = stA
		if false {
			_ = i
		}
		for j, b := range samples {
			if i == j {
				continue
			}
			for _, inc := range a.IncompatibleSampleTypes {
				if inc == b.SampleTypeID {
					return false
				}
			}
			// Pulse must not wait to be batched
			// check names via type id known defaults
			if a.SampleTypeID.String() == "aaaaaaaa-0001-4000-8000-000000000004" ||
				b.SampleTypeID.String() == "aaaaaaaa-0001-4000-8000-000000000004" {
				return false
			}
			// temperature overlap
			if a.TemperatureMaxC < b.TemperatureMinC || b.TemperatureMaxC < a.TemperatureMinC {
				return false
			}
		}
	}
	return true
}

