func (app *App) handleDisruption(w http.ResponseWriter, r *http.Request) {
	auth := getAuth(r)
	if !roleSelected(auth) {
		writeErr(w, 409, "role_not_selected", "select a role")
		return
	}
	if !adminOrDispatcher(auth) {
		writeErr(w, 403, "forbidden", "forbidden")
		return
	}
	var req struct {
		ResourceType   string `json:"resourceType"`
		ResourceID     string `json:"resourceId"`
		Reason         string `json:"reason"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, 400, "invalid_json", "invalid json")
		return
	}
	if req.ResourceType == "" || req.ResourceID == "" {
		writeErr(w, 400, "invalid_json", "resource required")
		return
	}
	at := time.Now().UTC()
	if req.OccurredAt != "" {
		t, err := parseTime(req.OccurredAt)
		if err != nil {
			writeErr(w, 400, "invalid_time", "invalid occurredAt")
			return
		}
		at = t
	}
	// deactivate resource if applicable
	if id, err := uuid.Parse(req.ResourceID); err == nil {
		switch req.ResourceType {
		case "node", "location", "laboratory":
			_ = app.Store.SetLocationActive(r.Context(), id, false)
			_, _ = app.Store.BumpNetworkRevision(r.Context())
			go app.rebuildServiceabilitySnapshot(r.Context())
		case "connection", "route":
			_ = app.Store.SetConnectionActive(r.Context(), id, false)
			_, _ = app.Store.BumpNetworkRevision(r.Context())
			go app.rebuildServiceabilitySnapshot(r.Context())
		case "worker":
			u, _ := app.Store.GetUserByID(r.Context(), id)
			if u != nil {
				_ = app.Store.SetWorkerAvailability(r.Context(), id, false, u.CapacityUnits)
			}
		}
	}
	affected := app.findAffectedJourneys(r.Context(), req.ResourceType, req.ResourceID)
	var results []map[string]any
	for _, j := range affected {
		// replan each
		sids, _ := app.Store.JourneySampleIDs(r.Context(), j.ID)
		if len(sids) == 0 {
			continue
		}
		sm, _ := app.Store.GetSample(r.Context(), sids[0])
		if sm == nil || sm.Status == StatusReceived || sm.Status == StatusCancelled {
			continue
		}
		holder := sm.CurrentHolderID
		st, _ := app.Store.GetSampleType(r.Context(), sm.SampleTypeID)
		origin := Coordinate{Latitude: sm.OriginLat, Longitude: sm.OriginLng}
		if sm.LatestLat != nil {
			origin = Coordinate{Latitude: *sm.LatestLat, Longitude: *sm.LatestLng}
		}
		res, _ := app.computeServiceability(r.Context(), origin, OriginNode, sm.OriginNodeID, sm.SampleTypeID, time.Now().UTC(), sm.DeliveryDeadline, sm.EarliestCollectionAt, sm.LatestCollectionAt, st != nil && st.RequiresCooledRoute)
		j.PlanVersion++
		if !res.Serviceable {
			sm.Status = StatusExpired
			sm.CurrentHolderID = holder
			_ = app.Store.UpdateSample(r.Context(), *sm)
			rs := "expired"
			j.ReplanStatus = &rs
			j.Valid = false
			_ = app.Store.UpdateJourney(r.Context(), j)
			results = append(results, map[string]any{"journeyId": j.ID.String(), "replanStatus": "expired"})
			continue
		}
		asgs, _ := app.Store.ListAssignmentsForJourney(r.Context(), j.ID)
		for _, a := range asgs {
			if a.Status != StatusCompleted {
				a.Status = StatusCancelled
				a.OfferedTo = nil
				_ = app.Store.UpdateAssignment(r.Context(), a)
			}
		}
		rs := "replanned"
		j.ReplanStatus = &rs
		j.Valid = true
		_ = app.Store.UpdateJourney(r.Context(), j)
		sm.CurrentHolderID = holder
		_ = app.Store.UpdateSample(r.Context(), *sm)
		results = append(results, map[string]any{"journeyId": j.ID.String(), "replanStatus": "replanned", "planVersion": j.PlanVersion})
	}
	if results == nil {
		results = []map[string]any{}
	}
	_ = at
	app.writeAudit(r.Context(), auth.User.ID.String(), auth.ActiveRole, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason})
	writeData(w, 200, map[string]any{"affected": results})
}

func (app *App) findAffectedJourneys(ctx context.Context, resourceType, resourceID string) []Journey {
	samples, _ := app.Store.ListSamples(ctx)
	seen := map[uuid.UUID]bool{}
	var out []Journey
	rid, _ := uuid.Parse(resourceID)
	for _, sm := range samples {
		if sm.ActiveJourneyID == nil || sm.Status == StatusReceived || sm.Status == StatusCancelled || sm.Status == StatusExpired {
			continue
		}
		if seen[*sm.ActiveJourneyID] {
			continue
		}
		hit := false
		if resourceType == "worker" && sm.CurrentHolderID != nil && sm.CurrentHolderID.String() == resourceID {
			hit = true
		}
		if (resourceType == "laboratory" || resourceType == "node" || resourceType == "location") && sm.TargetLaboratoryID != nil && *sm.TargetLaboratoryID == rid {
			hit = true
		}
		asgs, _ := app.Store.ListAssignmentsForSample(ctx, sm.ID)
		for _, a := range asgs {
			if a.Status == StatusCompleted {
				continue
			}
			if resourceType == "worker" && ((a.WorkerID != nil && a.WorkerID.String() == resourceID) || (a.OfferedTo != nil && a.OfferedTo.String() == resourceID)) {
				hit = true
			}
			if (resourceType == "node" || resourceType == "location" || resourceType == "laboratory") &&
				((a.NodeID != nil && *a.NodeID == rid) || (a.LaboratoryID != nil && *a.LaboratoryID == rid) ||
					(a.FromLocationID != nil && *a.FromLocationID == rid) || (a.ToLocationID != nil && *a.ToLocationID == rid)) {
				hit = true
			}
		}
		if hit {
			j, _ := app.Store.GetJourney(ctx, *sm.ActiveJourneyID)
			if j != nil {
				seen[j.ID] = true
				out = append(out, *j)
			}
		}
	}
	sort.Slice(out, func(i, k int) bool { return out[i].ID.String() < out[k].ID.String() })
	return out
}
"}

