{"path":"/workspace/frontend/src/api.ts","command":"create","file_text":"export type Role =
  | "requester"
  | "certified_collection_professional"
  | "relay_courier"
  | "node_handler"
  | "laboratory_intake_operator"
  | "dispatcher"
  | "administrator";

export type ApiError = {
  error: {
    code: string;
    message: string;
    details?: Record<string, unknown>;
  };
};

export type Envelope<T> = {
  data: T;
};

async function parse<T>(res: Response): Promise<T> {
  const text = await res.text();
  let body: any = {};
  try {
    body = text ? JSON.parse(text) : {};
  } catch {
    body = { raw: text };
  }
  if (!res.ok) {
    const err = body?.error ?? { code: "http_error", message: text || res.statusText };
    throw Object.assign(new Error(err.message || "request failed"), { status: res.status, body });
  }
  return body as T;
}

export async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const headers = new Headers(init.headers);
  if (init.body && !headers.has("Content-Type")) {
    headers.set("Content-Type", "application/json");
  }
  const res = await fetch(path, { ...init, headers, credentials: "include" });
  return parse<T>(res);
}

export function post<T>(path: string, body: unknown, extra?: RequestInit): Promise<T> {
  return api<T>(path, { method: "POST", body: JSON.stringify(body ?? {}), ...extra });
}

export function get<T>(path: string): Promise<T> {
  return api<T>(path, { method: "GET" });
}

